#!/usr/bin/env python3
"""usage: drive.py <file> <w> <h> [--keys k1 k2 ...] [--show] [--raw]
keys: strings sent literally; special: ^Tab, ^Down, ... prefix '^' -> send-keys named key"""
import subprocess, sys, os, re, time

def run(cmd, **kw):
    return subprocess.run(cmd, capture_output=True, **kw)

def capture(sess):
    r = run(['tmux','capture-pane','-p','-t',sess,'-e'])
    d = r.stdout.decode('utf-8','replace').split('\n')
    if d and d[-1]=='': d.pop()
    return d

def strip(lines):
    out=[]
    for l in lines:
        out.append(re.sub(r'\x1b\[[0-9;]*[A-Za-z]','',l))
    return out

def main():
    args=[a for a in sys.argv[1:]]
    keys=[]; show=True; raw=False; w=100; h=30; f=args[0]; i=1
    while i<len(args):
        if args[i]=='--keys':
            keys=args[i+1].split('|'); i+=2
        elif args[i]=='--w': w=int(args[i+1]); i+=2
        elif args[i]=='--h': h=int(args[i+1]); i+=2
        elif args[i]=='--hide': show=False; i+=1
        else: i+=1
    sess='s1'
    run(['tmux','kill-server'])
    run(['tmux','new-session','-d','-x',str(w),'-y',str(h),'-s',sess,'-c','/workspace',
         'env TERM=xterm-256color /workspace/executable '+f+'; echo EXIT=$?'])
    run(['tmux','set-option','-t',sess,'remain-on-exit','on'])
    time.sleep(0.9)
    before = capture(sess)
    beforev = strip(before)
    def send(k):
        if k.startswith('^'):
            run(['tmux','send-keys','-t',sess,k[1:]])
        elif k.startswith('M'):
            pass
        else:
            run(['tmux','send-keys','-t',sess,'-l',k])
        time.sleep(0.35)
    for k in keys: send(k)
    time.sleep(0.35)
    after=capture(sess); afterv=strip(after)
    dead = run(['tmux','display-message','-p','-t',sess,'#{pane_dead} #{pane_exit_status}']).stdout.decode().strip()
    if show:
        ch=False
        for i,(x,y) in enumerate(zip(beforev,afterv)):
            if x!=y: print(f'{i:3d}|{x}  ==>  {y}'); ch=True
        if not ch: print('(no change)')
        if len(afterv)>len(beforev):
            for j in range(len(beforev),len(afterv)): print(f'+++{j:3d}|{afterv[j]}')
        print('pane:',dead)
        if raw:
            for i,l in enumerate(after):
                print(i, repr(l)[:300])

if __name__=='__main__': main()
