#!/usr/bin/env python3
"""PTY harness: run executable in a pty, record raw output, send keys.
usage: pty.py <file> <w> <h> [keys...|--sleep t|--send b'..'|--screen]
"""
import os,pty,sys,time,fcntl,termios,struct,select,re,subprocess

class App:
    def __init__(self, args, w=100, h=30, cwd='/workspace'):
        self.master, self.slave = pty.openpty()
        fcntl.ioctl(self.slave, termios.TIOCSWINSZ, struct.pack('HHHH', h, w, 0, 0))
        pid = os.fork()
        if pid == 0:
            os.setsid()
            os.dup2(self.slave, 0); os.dup2(self.slave, 1); os.dup2(self.slave, 2)
            os.close(self.master); os.close(self.slave)
            os.chdir(cwd)
            env = dict(os.environ); env['TERM']='xterm-256color'; env['COLUMNS']=str(w); env['LINES']=str(h)
            os.execvpe('/workspace/executable', args, env)
            os._exit(1)
        os.close(self.slave)
        self.pid=pid; self.out=b''; self.w=w; self.h=h
    def read(self, timeout=0.2):
        r=[]; 
        while True:
            rl,_,_ = select.select([self.master],[],[],timeout)
            if not rl: break
            try: data=os.read(self.master, 65536)
            except OSError: break
            if not data: break
            self.out += data
        return self.out
    def send(self, s):
        os.write(self.master, s)
    def resize(self, w, h):
        self.w=w; self.h=h
        fcntl.ioctl(self.master, termios.TIOCSWINSZ, struct.pack('HHHH', h, w, 0, 0))
        self.send(b'\x1b')  # nothing
    def close(self):
        try: os.kill(self.pid, 9)
        except Exception: pass
        try: os.waitpid(self.pid, 0)
        except Exception: pass
        os.close(self.master)

def wait(ap, t=1.0):
    time.sleep(t); return ap.read(0.01)

def parse(s):
    """very simple ANSI parser producing a list of lines (strings) and tracking styles"""
    lines=[['']]
    styles=[['']]
    row=0; col=0; cur_style=''
    i=0
    n=len(s)
    def esc(j):
        # return (end_index, cmd)
        if s[j]=='\x1b':
            if j+1<n and s[j+1]=='[':
                k=j+2
                while k<n and not s[k].isalpha(): k+=1
                return (k+1, s[j+2:k+1])
            if j+1<n and s[j+1]==']':
                k=j+2
                while k<n and s[k] not in '\x07\x1b': k+=1
                return (k+2, '')
        return (j+1, s[j])
    while i<n:
        if s[i]=='\x1b':
            j,cmd=esc(i)
            m=re.match(r'^\[([0-9;]*)([A-Za-z])$', cmd)
            if m:
                params, code = m.group(1), m.group(2)
                if code=='H':
                    parts=params.split(';')
                    r_=int(parts[0]) if parts[0] else 1
                    c_=int(parts[1]) if len(parts)>1 and parts[1] else 1
                    row=r_-1; col=c_-1
                    while row>=len(lines): lines.append(['']); styles.append([''])
                elif code=='J' and params=='2':
                    lines=[['']]; styles=[['']]; row=0; col=0
                elif code=='K':
                    lines[row]=lines[row][:col]; styles[row]=styles[row][:col]
                elif code=='m':
                    cur_style=params
            i=j
            continue
        ch=s[i]
        if ch=='\r': col=0
        elif ch=='\n':
            row+=1; col=0
            while row>=len(lines): lines.append(['']); styles.append([''])
        elif ch=='\x08': col=max(0,col-1)
        else:
            while row>=len(lines): lines.append(['']); styles.append([''])
            ln=list(lines[row]); st=list(styles[row])
            while len(ln)<=col: ln.append(' '); st.append('')
            # if col is beyond length, pad
            if col < len(ln):
                pass
            ln[col:col+1]=[ch]; st[col:col+1]=[cur_style]
            lines[row]=''.join(ln); styles[row]=''.join(st)
            col+=1
        i+=1
    return [''.join(l) for l in lines], [''.join(l) for l in styles]
