    fn queue<W>(&self, mut w: W) -> io::Result<()> {
        let removed = self.from - self.to;
        if removed.contains(Modifier::REVERSED) { queue!(w, SetAttribute(CAttribute::NoReverse))?; }
        if removed.contains(Modifier::BOLD) {
