//! Minimal Thrift Compact Protocol reader (enough for parquet metadata / page headers).

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum TType {
    Stop,
    BoolTrue,
    BoolFalse,
    Byte,
    I16,
    I32,
    I64,
    Double,
    Binary,
    List,
    Set,
    Map,
    Struct,
}

pub struct Thrift<'a> {
    buf: &'a [u8],
    pos: usize,
    last: i16,
    depth: u32,
}

pub type TErr = String;

impl<'a> Thrift<'a> {
    pub fn new(buf: &'a [u8], pos: usize) -> Self {
        Thrift { buf, pos, last: 0, depth: 0 }
    }
    pub fn pos(&self) -> usize {
        self.pos
    }
    fn byte(&mut self) -> Result<u8, TErr> {
        if self.pos >= self.buf.len() {
            return Err("unexpected end of data".into());
        }
        let v = self.buf[self.pos];
        self.pos += 1;
        Ok(v)
    }
    fn uvarint(&mut self) -> Result<u64, TErr> {
        let mut r: u64 = 0;
        let mut s: u32 = 0;
        loop {
            let c = self.byte()?;
            r |= ((c & 0x7f) as u64) << s;
            if c & 0x80 == 0 {
                break;
            }
            s += 7;
            if s > 63 {
                return Err("varint too long".into());
            }
        }
        Ok(r)
    }
    fn zigzag(&mut self) -> Result<i64, TErr> {
        let v = self.uvarint()?;
        Ok(((v >> 1) as i64) ^ -((v & 1) as i64))
    }
    pub fn read_field_header(&mut self) -> Result<(i16, TType), TErr> {
        let hdr = self.byte()?;
        let t = match hdr & 0x0f {
            0 => TType::Stop,
            1 => TType::BoolTrue,
            2 => TType::BoolFalse,
            3 => TType::Byte,
            4 => TType::I16,
            5 => TType::I32,
            6 => TType::I64,
            7 => TType::Double,
            8 => TType::Binary,
            9 => TType::List,
            10 => TType::Set,
            11 => TType::Map,
            12 => TType::Struct,
            _ => return Err(format!("invalid thrift type {}", hdr & 0x0f)),
        };
        if t == TType::Stop {
            self.last = 0;
            return Ok((0, t));
        }
        let delta = (hdr >> 4) as i16;
        let id = if delta != 0 {
            self.last + delta
        } else {
            self.uvarint()? as i16
        };
        self.last = id;
        Ok((id, t))
    }
    /// Skip a value of the given type.
    pub fn skip(&mut self, t: TType) -> Result<(), TErr> {
        match t {
            TType::Stop | TType::BoolTrue | TType::BoolFalse => Ok(()),
            TType::Byte | TType::I16 | TType::I32 | TType::I64 => {
                self.zigzag()?;
                Ok(())
            }
            TType::Double => {
                if self.pos + 8 > self.buf.len() {
                    return Err("unexpected end of data".into());
                }
                self.pos += 8;
                Ok(())
            }
            TType::Binary => {
                let n = self.uvarint()? as usize;
                if self.pos + n > self.buf.len() {
                    return Err("unexpected end of data".into());
                }
                self.pos += n;
                Ok(())
            }
            TType::List | TType::Set => {
                let sz = self.byte()?;
                let et = elt(sz);
                let mut n = (sz >> 4) as u64;
                if n == 15 {
                    n = self.uvarint()?;
                }
                for _ in 0..n {
                    self.skip_value(et)?;
                }
                Ok(())
            }
            TType::Map => {
                let n = self.uvarint()?;
                if n == 0 {
                    return Ok(());
                }
                let kv = self.byte()?;
                let kt = elt(kv >> 4);
                let vt = elt(kv & 0x0f);
                for _ in 0..n {
                    self.skip_value(kt)?;
                    self.skip_value(vt)?;
                }
                Ok(())
            }
            TType::Struct => self.skip_struct(),
        }
    }
    pub fn skip_struct(&mut self) -> Result<(), TErr> {
        let saved_last = self.last;
        self.last = 0;
        self.depth += 1;
        if self.depth > 64 {
            return Err("struct nesting too deep".into());
        }
        loop {
            let (_, t) = self.read_field_header()?;
            if t == TType::Stop {
                break;
            }
            self.skip(t)?;
        }
        self.depth -= 1;
        self.last = saved_last;
        Ok(())
    }
    pub fn skip_value(&mut self, t: u8) -> Result<(), TErr> {
        let tt = match t {
            0 => TType::Stop,
            1 => TType::BoolTrue,
            2 => TType::BoolFalse,
            3 => TType::Byte,
            4 => TType::I16,
            5 => TType::I32,
            6 => TType::I64,
            7 => TType::Double,
            8 => TType::Binary,
            9 => TType::List,
            10 => TType::Set,
            11 => TType::Map,
            12 => TType::Struct,
            _ => return Err(format!("invalid element type {}", t)),
        };
        self.skip(tt)
    }
    pub fn i32v(&mut self) -> Result<i32, TErr> {
        Ok(self.zigzag()? as i32)
    }
    pub fn i64v(&mut self) -> Result<i64, TErr> {
        self.zigzag()
    }
    pub fn boolv(&mut self) -> Result<bool, TErr> {
        Ok(true)
    }
    pub fn binary(&mut self) -> Result<&'a [u8], TErr> {
        let n = self.uvarint()? as usize;
        if self.pos + n > self.buf.len() {
            return Err("unexpected end of data".into());
        }
        let s = &self.buf[self.pos..self.pos + n];
        self.pos += n;
        Ok(s)
    }
    pub fn string(&mut self) -> Result<String, TErr> {
        let b = self.binary()?;
        Ok(String::from_utf8_lossy(b).into_owned())
    }
    /// Begin reading a list; returns (element_type, len). Consumes the header.
    pub fn list_begin(&mut self) -> Result<(u8, usize), TErr> {
        let sz = self.byte()?;
        let et = elt(sz);
        let mut n = (sz >> 4) as usize;
        if n == 15 {
            n = self.uvarint()? as usize;
        }
        Ok((et, n))
    }
}

fn elt(sz: u8) -> u8 {
    sz & 0x0f
}
EOF
echo ok"}

