fn parse_logical_type(t: &mut Thrift) -> Result<LogicalType, TErr> {
    let mut lt = LogicalType::default();
    loop {
        let (id, ty) = t.read_field_header()?;
        if ty == TType::Stop {
            break;
        }
        match id {
            1 => {
                lt.kind = 1;
                t.skip(ty)?;
            } // STRING
            2 => {
                lt.kind = 2;
                t.skip(ty)?;
            } // MAP
            3 => {
                lt.kind = 3;
                t.skip(ty)?;
            } // LIST
            4 => {
                lt.kind = 4;
                t.skip(ty)?;
            } // ENUM
            5 => {
                lt.kind = 5;
                if ty == TType::Struct {
                    loop {
                        let (fid, ft) = t.read_field_header()?;
                        if ft == TType::Stop {
                            break;
                        }
                        match fid {
                            1 => lt.scale = t.i32v()?,
                            2 => lt.precision = t.i32v()?,
                            _ => t.skip(ft)?,
                        }
                    }
                } else {
                    t.skip(ty)?;
                }
            }
            6 => {
                lt.kind = 6;
                t.skip(ty)?;
            } // DATE
            7 => {
                lt.kind = 7; // TIME
                if ty == TType::Struct {
                    loop {
                        let (fid, ft) = t.read_field_header()?;
                        if ft == TType::Stop {
                            break;
                        }
                        match fid {
                            1 => lt.is_adjusted_utc = t.boolv()?,
                            2 => {
                                lt.unit = match ft {
                                    TType::I32 => 0,
                                    TType::I64 => 1,
                                    _ => 2,
                                };
                                t.skip(ft)?
                            }
                            _ => t.skip(ft)?,
                        }
                    }
                } else {
                    t.skip(ty)?;
                }
            }
            8 => {
                lt.kind = 8; // TIMESTAMP
                if ty == TType::Struct {
                    loop {
                        let (fid, ft) = t.read_field_header()?;
                        if ft == TType::Stop {
                            break;
                        }
                        match fid {
                            1 => lt.is_adjusted_utc = t.boolv()?,
                            2 => {
                                lt.unit = match ft {
                                    TType::I32 => 0,
                                    TType::I64 => 1,
                                    _ => 2,
                                };
                                t.skip(ft)?
                            }
                            _ => t.skip(ft)?,
                        }
                    }
                } else {
                    t.skip(ty)?;
                }
            }
            9 => {
                lt.kind = 9; // INTEGER
                if ty == TType::Struct {
                    loop {
                        let (fid, ft) = t.read_field_header()?;
                        if ft == TType::Stop {
                            break;
                        }
                        match fid {
                            1 => lt.bit_width = t.i32v()? as i8,
                            2 => lt.is_signed = t.boolv()?,
                            _ => t.skip(ft)?,
                        }
                    }
                } else {
                    t.skip(ty)?;
                }
            }
            10 => {
                lt.kind = 10;
                t.skip(ty)?;
            } // UNKNOWN
            11 => {
                lt.kind = 11;
                t.skip(ty)?;
            } // JSON
            12 => {
                lt.kind = 12;
                t.skip(ty)?;
            } // BSON
            13 => {
                lt.kind = 13;
                t.skip(ty)?;
            } // UUID
            _ => t.skip(ty)?,
        }
    }
    Ok(lt)
}

fn parse_statistics(t: &mut Thrift) -> Result<Statistics, TErr> {
    let mut s = Statistics::default();
    loop {
        let (id, ty) = t.read_field_header()?;
        if ty == TType::Stop {
            break;
        }
        match id {
            1 => s.max = Some(t.binary()?.to_vec()),
            2 => s.min = Some(t.binary()?.to_vec()),
            3 => s.null_count = Some(t.i64v()?),
            4 => s.distinct_count = Some(t.i64v()?),
            5 => s.max_value = Some(t.binary()?.to_vec()),
            6 => s.min_value = Some(t.binary()?.to_vec()),
            _ => t.skip(ty)?,
        }
    }
    Ok(s)
}

fn parse_column_meta(t: &mut Thrift) -> Result<ColumnMetaData, TErr> {
    let mut cm = ColumnMetaData::default();
    loop {
        let (id, ty) = t.read_field_header()?;
        if ty == TType::Stop {
            break;
        }
        match id {
            1 => cm.ptype = t.i32v()?,
            2 => {
                let (et, n) = t.list_begin()?;
                for _ in 0..n {
                    if et == 5 {
                        cm.encodings.push(t.i32v()?);
                    } else {
                        t.skip_value(et)?;
                    }
                }
            }
            3 => {
                let (et, n) = t.list_begin()?;
                for _ in 0..n {
                    if et == 8 {
                        cm.path_in_schema.push(t.string()?);
                    } else {
                        t.skip_value(et)?;
                    }
                }
            }
            4 => cm.codec = t.i32v()?,
            5 => cm.num_values = t.i64v()?,
            6 => cm.total_uncompressed_size = t.i64v()?,
            7 => cm.total_compressed_size = t.i64v()?,
            8 => t.skip(ty)?,
            9 => cm.data_page_offset = t.i64v()?,
            10 => cm.index_page_offset = Some(t.i64v()?),
            11 => cm.dictionary_page_offset = Some(t.i64v()?),
            12 => cm.statistics = Some(parse_statistics(t)?),
            13 => {
                let (et, n) = t.list_begin()?;
                for _ in 0..n {
                    if et == 12 {
                        let mut pes = PageEncodingStats::default();
                        loop {
                            let (fid, ft) = t.read_field_header()?;
                            if ft == TType::Stop {
                                break;
                            }
                            match fid {
                                1 => pes.page_type = t.i32v()?,
                                2 => pes.encoding = t.i32v()?,
                                3 => pes.count = t.i32v()?,
                                _ => t.skip(ft)?,
                            }
                        }
                        cm.encoding_stats.push(pes);
                    } else {
                        t.skip_value(et)?;
                    }
                }
            }
            14 => cm.bloom_filter_offset = Some(t.i64v()?),
            15 => cm.bloom_filter_length = Some(t.i32v()?),
            _ => t.skip(ty)?,
        }
    }
    Ok(cm)
}

fn parse_column_chunk(t: &mut Thrift) -> Result<ColumnChunk, TErr> {
    let mut cc = ColumnChunk::default();
    loop {
        let (id, ty) = t.read_field_header()?;
        if ty == TType::Stop {
            break;
        }
        match id {
            1 => cc.file_path = Some(t.string()?),
            2 => cc.file_offset = t.i64v()?,
            3 => cc.meta_data = Some(parse_column_meta(t)?),
            4 => cc.offset_index_offset = Some(t.i64v()?),
            5 => cc.offset_index_length = Some(t.i32v()?),
            6 => cc.column_index_offset = Some(t.i64v()?),
            7 => cc.column_index_length = Some(t.i32v()?),
            _ => t.skip(ty)?,
        }
    }
    Ok(cc)
}

fn parse_row_group(t: &mut Thrift) -> Result<RowGroup, TErr> {
    let mut rg = RowGroup::default();
    loop {
        let (id, ty) = t.read_field_header()?;
        if ty == TType::Stop {
            break;
        }
        match id {
            1 => {
                let (et, n) = t.list_begin()?;
                for _ in 0..n {
                    if et == 12 {
                        rg.columns.push(parse_column_chunk(t)?);
                    } else {
                        t.skip_value(et)?;
                    }
                }
            }
            2 => rg.total_byte_size = t.i64v()?,
            3 => rg.num_rows = t.i64v()?,
            4 => t.skip(ty)?,
            5 => rg.total_compressed_size = t.i64v()?,
            6 => rg.ordinal = Some(t.i32v()? as i16),
            _ => t.skip(ty)?,
        }
    }
    Ok(rg)
}

fn parse_schema_element(t: &mut Thrift) -> Result<SchemaElement, TErr> {
    let mut se = SchemaElement::default();
    loop {
        let (id, ty) = t.read_field_header()?;
        if ty == TType::Stop {
            break;
        }
        match id {
            1 => se.ptype = Some(t.i32v()?),
            2 => se.type_length = Some(t.i32v()?),
            3 => se.repetition = Some(t.i32v()?),
            4 => se.name = t.string()?,
            5 => se.num_children = Some(t.i32v()?),
            6 => se.converted_type = Some(t.i32v()?),
            7 => se.scale = Some(t.i32v()?),
            8 => se.precision = Some(t.i32v()?),
            9 => se.field_id = Some(t.i32v()?),
            10 => se.logical_type = Some(parse_logical_type(t)?),
            _ => t.skip(ty)?,
        }
    }
    Ok(se)
}

pub fn parse_file_metadata(buf: &[u8]) -> Result<FileMetaData, TErr> {
    let mut t = Thrift::new(buf, 0);
    let mut fm = FileMetaData::default();
    loop {
        let (id, ty) = t.read_field_header()?;
        if ty == TType::Stop {
            break;
        }
        match id {
            1 => fm.version = t.i32v()?,
            2 => {
                let (et, n) = t.list_begin()?;
                for _ in 0..n {
                    if et == 12 {
                        fm.schema.push(parse_schema_element(&mut t)?);
                    } else {
                        t.skip_value(et)?;
                    }
                }
            }
            3 => fm.num_rows = t.i64v()?,
            4 => {
                let (et, n) = t.list_begin()?;
                for _ in 0..n {
                    if et == 12 {
                        fm.row_groups.push(parse_row_group(&mut t)?);
                    } else {
                        t.skip_value(et)?;
                    }
                }
            }
            5 => {
                let (et, n) = t.list_begin()?;
                for _ in 0..n {
                    if et == 12 {
                        let mut k = String::new();
                        let mut v = String::new();
                        loop {
                            let (fid, ft) = t.read_field_header()?;
                            if ft == TType::Stop {
                                break;
                            }
                            match fid {
                                1 => k = t.string()?,
                                2 => v = t.string()?,
                                _ => t.skip(ft)?,
                            }
                        }
                        fm.key_value_metadata.push((k, v));
                    } else {
                        t.skip_value(et)?;
                    }
                }
            }
            6 => fm.created_by = Some(t.string()?),
            7 => {
                fm.column_orders_present = true;
                t.skip(ty)?;
            }
            _ => t.skip(ty)?,
        }
    }
    Ok(fm)
}
