pub mod snappy {
    use super::super::error::PqError;
    pub fn uncompress(data: &[u8]) -> Result<Vec<u8>, PqError> {
        // varint length
        let mut pos = 0usize;
        let mut len: u64 = 0;
        let mut shift = 0u32;
        loop {
            if pos >= data.len() {
                return Err(PqError::Codec("snappy: truncated header".into()));
            }
            let c = data[pos];
            pos += 1;
            len |= ((c & 0x7f) as u64) << shift;
            if c & 0x80 == 0 {
                break;
            }
            shift += 7;
            if shift > 35 {
                return Err(PqError::Codec("snappy: bad varint".into()));
            }
        }
        let mut out: Vec<u8> = Vec::with_capacity(len as usize);
        while pos < data.len() {
            let tag = data[pos];
            let t = tag & 0x03;
            match t {
                0 => {
                    // literal
                    let mut l = (tag >> 2) as usize;
                    pos += 1;
                    if l >= 60 {
                        let extra = l - 59;
                        if pos + extra > data.len() {
                            return Err(PqError::Codec("snappy: truncated literal".into()));
                        }
                        let mut v: usize = 0;
                        for i in 0..extra {
                            v |= (data[pos + i] as usize) << (8 * i);
                        }
                        pos += extra;
                        l = v;
                    }
                    l += 1;
                    if pos + l > data.len() {
                        return Err(PqError::Codec("snappy: truncated literal".into()));
                    }
                    out.extend_from_slice(&data[pos..pos + l]);
                    pos += l;
                }
                1 => {
                    // copy with 1-byte offset
                    if pos + 1 >= data.len() {
                        return Err(PqError::Codec("snappy: truncated copy".into()));
                    }
                    let l = 4 + ((tag >> 2) & 0x07) as usize;
                    let off = (((tag >> 5) as usize) << 8) | data[pos + 1] as usize;
                    pos += 2;
                    copy(&mut out, off, l)?;
                }
                2 => {
                    if pos + 2 >= data.len() {
                        return Err(PqError::Codec("snappy: truncated copy".into()));
                    }
                    let l = ((tag >> 2) as usize) + 1;
                    let off = data[pos + 1] as usize | ((data[pos + 2] as usize) << 8);
                    pos += 3;
                    copy(&mut out, off, l)?;
                }
                _ => {
                    if pos + 4 >= data.len() {
                        return Err(PqError::Codec("snappy: truncated copy".into()));
                    }
                    let l = ((tag >> 2) as usize) + 1;
                    let off = data[pos + 1] as usize
                        | ((data[pos + 2] as usize) << 8)
                        | ((data[pos + 3] as usize) << 16)
                        | ((data[pos + 4] as usize) << 24);
                    pos += 5;
                    copy(&mut out, off, l)?;
                }
            }
        }
        if out.len() != len as usize {
            // Some writers are sloppy about the declared length; accept if longer
            if out.len() < len as usize {
                return Err(PqError::Codec(format!(
                    "snappy: decompressed {} bytes, expected {}",
                    out.len(),
                    len
                )));
            }
        }
        Ok(out)
    }
    fn copy(out: &mut Vec<u8>, off: usize, len: usize) -> Result<(), PqError> {
        if off == 0 || off > out.len() {
            return Err(PqError::Codec("snappy: invalid copy offset".into()));
        }
        let start = out.len() - off;
        for i in 0..len {
            let b = out[start + i];
            out.push(b);
        }
        Ok(())
    }
}

pub mod gzip {
    use super::super::error::PqError;
    pub fn uncompress(data: &[u8], size: usize) -> Result<Vec<u8>, PqError> {
        let mut d = flate2::read::MultiGzDecoder::new(data);
        use std::io::Read;
