pub mod lz4 {
    use super::super::error::PqError;

    /// Hadoop-style LZ4: 4-byte big-endian block length prefixes.
    pub fn uncompress_hadoop(data: &[u8], _size: usize) -> Result<Vec<u8>, PqError> {
        let mut out: Vec<u8> = Vec::new();
        let mut pos = 0usize;
        while pos < data.len() {
            if pos + 4 > data.len() {
                // trailing partial block: treat as raw
                out.extend_from_slice(&data[pos..]);
                break;
            }
            let n = ((data[pos] as usize) << 24)
                | ((data[pos + 1] as usize) << 16)
                | ((data[pos + 2] as usize) << 8)
                | (data[pos + 3] as usize);
            pos += 4;
            if pos + n > data.len() {
                return Err(PqError::Codec("lz4: truncated block".into()));
            }
            uncompress_block_into(&data[pos..pos + n], &mut out)?;
            pos += n;
        }
        Ok(out)
    }

    pub fn uncompress_block(data: &[u8], _size: usize) -> Result<Vec<u8>, PqError> {
        let mut out = Vec::new();
        uncompress_block_into(data, &mut out)?;
        Ok(out)
    }

    pub fn uncompress_block_into(data: &[u8], out: &mut Vec<u8>) -> Result<(), PqError> {
        let mut pos = 0usize;
        let end = data.len();
        while pos < end {
            let token = data[pos];
            pos += 1;
            let mut lit_len = (token >> 4) as usize;
            if lit_len == 15 {
                loop {
                    if pos >= end {
                        return Err(PqError::Codec("lz4: truncated literal length".into()));
                    }
                    let b = data[pos] as usize;
                    pos += 1;
                    lit_len += b;
                    if b != 255 {
                        break;
                    }
                }
            }
            if pos + lit_len > end {
                return Err(PqError::Codec("lz4: truncated literal".into()));
            }
            out.extend_from_slice(&data[pos..pos + lit_len]);
            pos += lit_len;
            if pos >= end {
                break;
            }
            if pos + 2 > end {
                return Err(PqError::Codec("lz4: truncated offset".into()));
            }
            let off = data[pos] as usize | ((data[pos + 1] as usize) << 8);
            pos += 2;
            if off == 0 {
                return Err(PqError::Codec("lz4: zero offset".into()));
            }
            let mut match_len = (token & 0x0f) as usize + 4;
            if (token & 0x0f) == 15 {
                loop {
                    if pos >= end {
                        return Err(PqError::Codec("lz4: truncated match length".into()));
                    }
                    let b = data[pos] as usize;
                    pos += 1;
                    match_len += b;
                    if b != 255 {
                        break;
                    }
                }
            }
            let start = out.len().checked_sub(off).ok_or_else(|| {
                PqError::Codec("lz4: offset beyond output".to_string())
            })?;
            for i in 0..match_len {
                let b = out[start + i];
                out.push(b);
            }
        }
        Ok(())
    }
}

pub mod zstd {
    use super::super::error::PqError;

    pub fn uncompress(data: &[u8]) -> Result<Vec<u8>, PqError> {
        let mut out = Vec::new();
        let mut pos = 0usize;
        // magic
        if data.len() < 4 || &data[0..4] != b"\x28\xb5\x2f\xfd" {
            // maybe skippable frame
            return Err(PqError::Codec("zstd: bad magic".into()));
        }
        pos = 4;
        while pos < data.len() {
            let fh = u32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]);
            pos += 4;
            let fcs_flag = (fh >> 6) & 3;
            let single_segment = (fh >> 5) & 1 != 0;
            let checksum = (fh >> 2) & 1 != 0;
            let dict_id_flag = (fh & 3) as u8;
            let mut fsize: u64 = 0;
            match fcs_flag {
                0 => {
                    if single_segment {
                        if pos >= data.len() {
                            return Err(PqError::Codec("zstd: truncated frame".into()));
                        }
                        fsize = data[pos] as u64;
                        pos += 1;
                    } else {
                        if pos + 2 > data.len() {
                            return Err(PqError::Codec("zstd: truncated frame".into()));
                        }
                        fsize = ((data[pos] as u64) | ((data[pos + 1] as u64) << 8)) + 256;
                        pos += 2;
                    }
                }
                1 => {
                    if pos + 4 > data.len() {
                        return Err(PqError::Codec("zstd: truncated frame".into()));
                    }
                    fsize = u32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]) as u64;
                    pos += 4;
                }
                _ => {
                    if pos + 8 > data.len() {
                        return Err(PqError::Codec("zstd: truncated frame".into()));
                    }
                    fsize = u64::from_le_bytes([
                        data[pos],
                        data[pos + 1],
                        data[pos + 2],
                        data[pos + 3],
                        data[pos + 4],
                        data[pos + 5],
                        data[pos + 6],
                        data[pos + 7],
                    ]);
                    pos += 8;
                }
            }
            match dict_id_flag {
                1 => pos += 1,
                2 => pos += 2,
                3 => pos += 4,
                _ => {}
            }
            let wlog = 10 + ((fh >> 10) & 0xf) as u32;
            let blocks_start = pos;
            let _ = wlog;
            // decode blocks
            let mut last_block = false;
            let mut window: Vec<u8> = Vec::new();
            let mut block_out: Vec<u8> = Vec::new();
            while !last_block {
                if pos + 3 > data.len() {
                    return Err(PqError::Codec("zstd: truncated block header".into()));
                }
                let bh = u32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]);
                pos += 3;
                last_block = bh & 1 != 0;
                let btype = (bh >> 1) & 3;
                let bsize = (bh >> 3) as usize;
                block_out.clear();
                match btype {
                    0 => {
                        // raw
                        if pos + bsize > data.len() {
                            return Err(PqError::Codec("zstd: truncated raw block".into()));
                        }
                        block_out.extend_from_slice(&data[pos..pos + bsize]);
                        pos += bsize;
                    }
                    1 => {
                        // rle
                        if pos >= data.len() {
                            return Err(PqError::Codec("zstd: truncated rle block".into()));
                        }
                        let b = data[pos];
                        pos += 1;
                        block_out.resize(bsize, b);
                    }
                    2 => {
                        if pos + bsize > data.len() {
                            return Err(PqError::Codec("zstd: truncated compressed block".into()));
                        }
                        let src = &data[pos..pos + bsize];
                        pos += bsize;
                        decompress_block(src, &mut block_out)?;
                    }
                    _ => {
                        last_block = true;
                        break;
                    }
                }
                window.extend_from_slice(&block_out);
                out.extend_from_slice(&block_out);
                if window.len() > 1 << 22 {
                    let cut = window.len() - (1 << 22);
                    window.drain(0..cut);
                }
            }
            if checksum {
                pos += 4;
            }
            let _ = blocks_start;
        }
        Ok(out)
    }

    fn decompress_block(src: &[u8], out: &mut Vec<u8>) -> Result<(), PqError> {
        let mut p = 0usize;
        if src.is_empty() {
            return Err(PqError::Codec("zstd: empty block".into()));
        }
        let lit_section_type = src[p] & 3;
        let size_format = (src[p] >> 2) & 3;
        p += 1;
        // ---- literals section header
        let (regen_size, huff_size, lit_comp, huf_data) = match lit_section_type {
            0 | 1 => {
                // raw literals
                let mut lit_len: usize = (src[0] >> 3) as usize;
                let mut hdr = 1usize;
                match lit_section_type {
                    0 => {
                        if lit_len < 31 {
                            // 1 byte header (already consumed), length = lit_len
                        } else {
                            // 3 byte header
                            if src.len() < 3 {
                                return Err(PqError::Codec("zstd: truncated literals".into()));
                            }
                            lit_len = (((src[0] >> 3) as usize) & 0x1f)
                                | ((src[1] as usize) << 5)
                                | ((src[2] as usize) << 13);
                            hdr = 3;
                        }
                    }
                    _ => {
                        if src.len() < 2 {
                            return Err(PqError::Codec("zstd: truncated literals".into()));
                        }
                        lit_len = ((src[0] >> 3) as usize) | ((src[1] as usize) << 5);
                        hdr = 2;
                    }
                }
                let _ = hdr;
                if p - 1 + hdr + lit_len > src.len() {
                    return Err(PqError::Codec("zstd: truncated literals".into()));
                }
                let start = hdr;
                let data = src[start..start + lit_len].to_vec();
                (0usize, 0usize, 0u8, data)
            }
            2 => {
                // huffman-compressed literals
                let mut lit_len: usize;
                let mut ns: usize;
                let mut hs: usize;
                match size_format {
                    0 => {
                        if src.len() < 4 {
                            return Err(PqError::Codec("zstd: truncated literals".into()));
                        }
                        lit_len = (((src[0] >> 4) as usize) & 0x0f)
                            | ((src[1] as usize) << 4)
                            | ((src[2] as usize) << 12);
                        ns = src[3] as usize;
                        p = 4;
                    }
                    1 => {
                        if src.len() < 4 {
                            return Err(PqError::Codec("zstd: truncated literals".into()));
                        }
                        lit_len = (((src[0] >> 4) as usize) & 0x0f)
                            | ((src[1] as usize) << 4)
                            | ((src[2] as usize) << 12);
                        ns = (src[3] as usize) | (((src[0] >> 2) as usize & 3) << 8);
                        ns &= 0xfff;
                        ns = src[3] as usize | ((src[2] >> 6) as usize) << 8;
                        ns &= 0x3ff;
                        p = 4;
                        // recompute: regen 20 bits, hsize 10 bits
                        lit_len = (((src[0] >> 4) as usize) & 0x0f)
                            | ((src[1] as usize) << 4)
                            | (((src[2] as usize) & 0x3f) << 12);
                        ns = ((src[2] >> 6) as usize) | ((src[3] as usize) << 2);
                        ns &= 0x3ff;
                    }
                    2 => {
                        if src.len() < 3 {
                            return Err(PqError::Codec("zstd: truncated literals".into()));
                        }
                        lit_len = (((src[0] >> 4) as usize) & 0x0f)
                            | ((src[1] as usize) << 4)
                            | (((src[2] as usize) & 0x0f) << 12);
                        ns = ((src[2] >> 4) as usize) & 0x0f;
                        p = 3;
                    }
                    _ => {
                        if src.len() < 3 {
                            return Err(PqError::Codec("zstd: truncated literals".into()));
                        }
                        lit_len = (((src[0] >> 4) as usize) & 0x0f) | ((src[1] as usize) << 4);
                        ns = ((src[1] >> 6) as usize) | (((src[2] as usize) & 0x3f) << 2);
                        p = 3;
                    }
                }
                let hsize = match size_format {
                    0 => (ns >> 3) as usize,
                    _ => (ns >> 3) as usize,
                };
                let huff_start = p;
                if huff_start + hsize > src.len() {
                    return Err(PqError::Codec("zstd: truncated huffman table".into()));
                }
                let huf = src[huff_start..huff_start + hsize].to_vec();
                let lstart = huff_start + hsize;
                if lstart + lit_len > src.len() {
                    return Err(PqError::Codec("zstd: truncated literals".into()));
                }
                let ldata = src[lstart..lstart + lit_len].to_vec();
                (lit_len, hsize, 2, huf)
            }
            _ => {
                return Err(PqError::nyi("zstd: RLE literals not supported"));
            }
        };
        let _ = regen_size;
        let _ = huff_size;
        let mut literals: Vec<u8> = Vec::new();
        if lit_comp == 0 {
            literals = huf_data;
        } else {
            let table = HuffmanTable::build(&huf_data)?;
            literals = table.decode(&huf_data, &literals)?;
            literals.clear();
            literals = huf_data.clone();
        }
        let _ = &mut literals;
        Err(PqError::nyi("zstd: full block decoding not implemented"))
    }

    struct HuffmanTable;
    impl HuffmanTable {
        fn build(_src: &[u8]) -> Result<Self, PqError> {
            Ok(HuffmanTable)
        }
        fn decode(&self, _src: &[u8], _out: &Vec<u8>) -> Result<Vec<u8>, PqError> {
            Ok(Vec::new())
        }
    }
}
