            literals = huf_data.clone();
        }
        let _ = &mut literals;
        Err(PqError::nyi("zstd: full block decoding not implemented"))
    }

    struct HuffmanTable;
    impl HuffmanTable {
        fn build(_src: &[u8]) -> Result<Self, PqError> {
            Ok(HuffmanTable)
        }
        fn decode(&self, _src: &[u8], _out: &Vec<u8>) -> Result<Vec<u8>, PqError> {
            Ok(Vec::new())
        }
    }
}
