//! Page decoding: PLAIN, RLE/bit-packed levels, dictionaries, delta encodings.

use super::error::PqError;

/// Reads bits LSB-first from a slice.
pub struct BitReader<'a> {
    pub buf: &'a [u8],
    pub pos: usize, // bit position
}

impl<'a> BitReader<'a> {
    pub fn new(buf: &'a [u8]) -> Self {
        BitReader { buf, pos: 0 }
    }
    pub fn remaining_bits(&self) -> usize {
        self.buf.len() * 8 - self.pos
    }
    pub fn read_bits(&mut self, n: usize) -> Result<u64, PqError> {
        if n == 0 {
            return Ok(0);
        }
        if self.pos + n > self.buf.len() * 8 {
            // allow reading past the end (treated as zeros)
            let avail = self.buf.len() * 8 - self.pos;
            if avail == 0 {
                self.pos += n;
                return Ok(0);
            }
            let v = self.read_bits(avail)?;
            self.pos += n - avail;
            return Ok(v);
        }
        let mut v: u64 = 0;
        let mut got = 0;
        while got < n {
            let byte_idx = self.pos / 8;
            let bit_idx = self.pos % 8;
            let take = std::cmp::min(n - got, 8 - bit_idx);
            let mask = ((1u16 << take) - 1) as u8;
            let bits = (self.buf[byte_idx] >> bit_idx) & mask;
            v |= (bits as u64) << got;
            got += take;
            self.pos += take;
        }
        Ok(v)
    }
}

/// Decodes RLE/bit-packed hybrid encoding of level values.
pub fn decode_rle_levels(
    data: &[u8],
    bit_width: u8,
    num_levels: usize,
) -> Result<Vec<i16>, PqError> {
    let mut out: Vec<i16> = Vec::with_capacity(num_levels);
    if bit_width == 0 {
        out.resize(num_levels, 0);
        return Ok(out);
    }
    let mut br = BitReader::new(data);
    let mut read_varint = |br: &mut BitReader| -> Result<u64, PqError> {
        let mut r: u64 = 0;
        let mut shift = 0u32;
        loop {
            // bytes are read 8 bits at a time from the bitstream
            let b = br.read_bits(8)? as u64;
            r |= (b & 0x7f) << shift;
            shift += 7;
            if b & 0x80 == 0 {
                break;
            }
            if shift > 56 {
                return Err(PqError::Corrupt("rle varint too long".into()));
            }
        }
        Ok(r)
    };
    while out.len() < num_levels {
        let header = read_varint(&mut br)?;
        if header & 1 == 0 {
            // RLE run
            let count = (header >> 1) as usize;
            let value = br.read_bits(bit_width as usize)? as i16;
            for _ in 0..count {
                if out.len() >= num_levels {
                    break;
                }
                out.push(value);
            }
        } else {
            // bit-packed run: 8 values
            let count = (header >> 1) as usize * 8;
            for _ in 0..count {
                if out.len() >= num_levels {
                    break;
                }
                let v = br.read_bits(bit_width as usize)? as i16;
                out.push(v);
            }
        }
        if out.len() > num_levels + 8 {
            break;
        }
    }
    out.resize(num_levels, 0);
    Ok(out)
}

/// Values decoded from a page (already decompressed), before dictionary resolution.
#[derive(Debug, Clone)]
pub enum RawValues {
    Int32(Vec<i32>),
    Int64(Vec<i64>),
    Int96(Vec<[u32; 3]>),
    Float(Vec<f32>),
    Double(Vec<f64>),
    ByteArray(Vec<Vec<u8>>),
    Bool(Vec<bool>),
}

impl RawValues {
    pub fn len(&self) -> usize {
        match self {
            RawValues::Int32(v) => v.len(),
            RawValues::Int64(v) => v.len(),
            RawValues::Int96(v) => v.len(),
            RawValues::Float(v) => v.len(),
            RawValues::Double(v) => v.len(),
            RawValues::ByteArray(v) => v.len(),
