                        data[pos + 4 * k],
                        data[pos + 4 * k + 1],
                        data[pos + 4 * k + 2],
                        data[pos + 4 * k + 3],
                    ]);
                }
                v.push(w);
                pos += 12;
            }
            Ok(RawValues::Int96(v))
        }
        4 => {
            let mut v = Vec::with_capacity(count);
            for _ in 0..count {
                if pos + 4 > data.len() {
                    return Err(PqError::Corrupt("truncated float data".into()));
                }
                v.push(f32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]));
                pos += 4;
            }
            Ok(RawValues::Float(v))
        }
        5 => {
            let mut v = Vec::with_capacity(count);
            for _ in 0..count {
                if pos + 8 > data.len() {
                    return Err(PqError::Corrupt("truncated double data".into()));
                }
                v.push(f64::from_le_bytes([
                    data[pos],
                    data[pos + 1],
                    data[pos + 2],
                    data[pos + 3],
                    data[pos + 4],
                    data[pos + 5],
                    data[pos + 6],
                    data[pos + 7],
                ]));
                pos += 8;
            }
            Ok(RawValues::Double(v))
        }
        6 => {
            let mut v = Vec::with_capacity(count);
            for _ in 0..count {
                if pos + 4 > data.len() {
                    return Err(PqError::Corrupt("truncated byte array".into()));
                }
                let n = u32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]) as usize;
                pos += 4;
                if pos + n > data.len() {
                    return Err(PqError::Corrupt("truncated byte array data".into()));
                }
                v.push(data[pos..pos + n].to_vec());
                pos += n;
            }
            Ok(RawValues::ByteArray(v))
        }
        7 => {
            let tl = type_length as usize;
            if tl == 0 {
                return Err(PqError::Corrupt("fixed_len_byte_array with length 0".into()));
            }
            let mut v = Vec::with_capacity(count);
            for _ in 0..count {
                if pos + tl > data.len() {
                    return Err(PqError::Corrupt("truncated fixed byte array".into()));
                }
                v.push(data[pos..pos + tl].to_vec());
                pos += tl;
            }
            Ok(RawValues::ByteArray(v))
        }
        other => Err(PqError::Corrupt(format!("unexpected parquet type: {}", other))),
    }
}

/// DELTA_BINARY_PACKED decoder (INT32/INT64)
pub fn read_delta_binary_packed(data: &[u8], count: usize) -> Result<RawValues, PqError> {
    let mut r = ByteReader::new(data);
    let block_size = r.read_uvarint()? as usize;
    let miniblock_count = r.read_uvarint()? as usize;
    let total_count = r.read_uvarint()? as usize;
    let first_value = r.read_zigzag()?;
    let n = if count == 0 { total_count } else { count };
    let mut out: Vec<i64> = Vec::with_capacity(n);
    if n == 0 {
        return Ok(RawValues::Int64(Vec::new()));
    }
    out.push(first_value);
    let mut values_per_block = block_size; // block size
    let mut i = 1usize;
    let mut last = first_value;
    while i < n {
        let min_delta = r.read_zigzag()?;
        // read miniblock widths
        let mut widths = Vec::with_capacity(values_per_block);
        for _ in 0..miniblock_count {
            widths.push(r.read_byte()? as usize);
        }
        let per_mini = values_per_block / miniblock_count.max(1);
        for w in widths {
            if i >= n {
                // still need to skip the block data
                let bits = w * per_mini;
                let nbytes = (bits + 7) / 8;
                r.skip(nbytes)?;
                continue;
            }
            let bits = w * per_mini;
            let nbytes = (bits + 7) / 8;
            if r.pos + nbytes > r.buf.len() {
                return Err(PqError::Corrupt("delta binary packed: truncated".into()));
            }
            let br = BitReader::new(&r.buf[r.pos..r.pos + nbytes]);
            r.pos += nbytes;
            let mut br2 = br;
            for k in 0..per_mini {
                if i >= n {
                    break;
                }
                let d = if w == 0 {
                    0i64
                } else {
                    br2.read_bits(w)? as i64
                };
                let v = last + min_delta + d;
                out.push(v);
                last = v;
                i += 1;
            }
        }
    }
    out.resize(n, 0);
    Ok(RawValues::Int64(out))
}

pub struct ByteReader<'a> {
    pub buf: &'a [u8],
    pub pos: usize,
}

impl<'a> ByteReader<'a> {
    pub fn new(buf: &'a [u8]) -> Self {
        ByteReader { buf, pos: 0 }
    }
    pub fn read_byte(&mut self) -> Result<u8, PqError> {
        if self.pos >= self.buf.len() {
            return Err(PqError::Corrupt("unexpected end of data".into()));
        }
        let v = self.buf[self.pos];
        self.pos += 1;
        Ok(v)
    }
    pub fn skip(&mut self, n: usize) -> Result<(), PqError> {
        if self.pos + n > self.buf.len() {
            return Err(PqError::Corrupt("unexpected end of data".into()));
        }
        self.pos += n;
        Ok(())
    }
    pub fn read_uvarint(&mut self) -> Result<u64, PqError> {
        let mut r: u64 = 0;
        let mut shift = 0u32;
        loop {
            let b = self.read_byte()? as u64;
            r |= (b & 0x7f) << shift;
            shift += 7;
            if b & 0x80 == 0 {
                break;
            }
            if shift > 63 {
                return Err(PqError::Corrupt("varint too long".into()));
            }
        }
        Ok(r)
    }
    pub fn read_zigzag(&mut self) -> Result<i64, PqError> {
        let v = self.read_uvarint()?;
        Ok(((v >> 1) as i64) ^ -((v & 1) as i64))
    }
    pub fn read_bytes(&mut self, n: usize) -> Result<&'a [u8], PqError> {
        if self.pos + n > self.buf.len() {
            return Err(PqError::Corrupt("unexpected end of data".into()));
        }
        let s = &self.buf[self.pos..self.pos + n];
        self.pos += n;
        Ok(s)
    }
}
