//! Error type mirroring the messages produced by the original tool.

#[derive(Debug)]
pub enum PqError {
    /// A wrapped io::Error message (printed as the main() error).
    Io(String),
    /// A "Parquet error: ..." message.
    Parquet(String),
    /// A "parquet: File out of specification: ..." message.
    Spec(String),
    /// Internal corruption
    Corrupt(String),
    /// Unsupported feature
    Codec(String),
    Nyi(String),
}

impl PqError {
    pub fn nyi(s: &str) -> PqError {
        PqError::Nyi(s.to_string())
    }
    pub fn io(s: &str) -> PqError {
        PqError::Io(s.to_string())
    }
    pub fn parquet(s: &str) -> PqError {
        PqError::Parquet(s.to_string())
    }
    pub fn spec(s: &str) -> PqError {
        PqError::Spec(s.to_string())
    }
    pub fn corrupt(s: &str) -> PqError {
        PqError::Corrupt(s.to_string())
    }
    /// The message shown to the user (without the "Error: " prefix)
    pub fn user_message(&self) -> String {
        match self {
            PqError::Io(s) => format!("Custom {{ kind: Other, error: \"{}\" }}", s),
            PqError::Parquet(s) => format!("Custom {{ kind: Other, error: \"Parquet error: {}\" }}", s),
            PqError::Spec(s) => format!(
                "Custom {{ kind: Other, error: \"parquet: File out of specification: {}\" }}",
                s
            ),
            PqError::Corrupt(s) => format!("Custom {{ kind: Other, error: \"Parquet error: {}\" }}", s),
            PqError::Codec(s) => format!("Custom {{ kind: Other, error: \"Parquet error: {}\" }}", s),
            PqError::Nyi(s) => format!("Custom {{ kind: Other, error: \"Parquet error: {}\" }}", s),
        }
    }
}
