//! Parquet file reader: footer metadata, page decoding, value assembly.

pub mod error;
pub mod thrift;
pub mod metadata;
pub mod decode;
pub mod compress;
pub mod values;

use error::PqError;
use metadata::*;
use values::Val;

#[derive(Debug, Clone)]
pub struct Node {
    pub name: String,
    pub repetition: i32,
    pub ptype: i32,
    pub type_length: i32,
    pub logical: LogicalType,
    pub converted_type: Option<i32>,
    pub scale: i32,
    pub precision: i32,
    pub children: Vec<usize>,
    pub max_def: i16,
    pub max_rep: i16,
    pub leaf: Option<usize>,
}

/// Leaf column descriptor (a leaf in the schema tree).
#[derive(Debug, Clone)]
pub struct Leaf {
    pub node: usize,
    pub path: Vec<String>,
}

pub struct ParquetFile {
    pub data: Vec<u8>,
    pub meta: FileMetaData,
    pub nodes: Vec<Node>,
    pub root: usize,
    pub leaves: Vec<Leaf>,
}

impl ParquetFile {
    pub fn read(path: &str) -> Result<ParquetFile, PqError> {
        let data = match std::fs::read(path) {
            Ok(d) => d,
            Err(e) => {
                return Err(PqError::Io(format!("{}", e)));
            }
        };
        if data.len() < 12 || &data[0..4] != b"PAR1" || &data[data.len() - 4..] != b"PAR1" {
            return Err(PqError::parquet("Invalid Parquet file. Corrupt footer"));
        }
        let len = data.len();
        let meta_len =
            u32::from_le_bytes([data[len - 8], data[len - 7], data[len - 6], data[len - 5]]) as usize;
        if meta_len == 0 || len < 8 + meta_len {
            return Err(PqError::parquet("Invalid Parquet file. Corrupt footer"));
        }
        let start = len - 8 - meta_len;
        let meta = match metadata::parse_file_metadata(&data[start..start + meta_len]) {
            Ok(m) => m,
            Err(e) => return Err(PqError::parquet(format!("Could not parse metadata: {}", e))),
        };
        let mut pf = ParquetFile {
            data,
            meta,
            nodes: Vec::new(),
            root: 0,
            leaves: Vec::new(),
        };
        pf.build_schema()?;
        Ok(pf)
    }

    fn build_schema(&mut self) -> Result<(), PqError> {
        if self.meta.schema.is_empty() {
            return Err(PqError::parquet("empty schema"));
        }
        // Build the tree iteratively
        let n = self.meta.schema.len();
        self.nodes = Vec::with_capacity(n);
        let mut idx = 0usize;
        // stack of (node_index, remaining_children)
        let mut stack: Vec<(usize, i32)> = Vec::new();
        let mut leaf_count = 0usize;
        let mut root = usize::MAX;
        while idx < n {
            let se = &self.meta.schema[idx];
            let node = Node {
                name: se.name.clone(),
                repetition: se.repetition.unwrap_or(0),
                ptype: se.ptype.unwrap_or(0),
                type_length: se.type_length.unwrap_or(0),
                logical: se.logical_type.clone().unwrap_or_default(),
                converted_type: se.converted_type,
                scale: se.scale.unwrap_or(0),
                precision: se.precision.unwrap_or(0),
                children: Vec::new(),
                max_def: 0,
                max_rep: 0,
                leaf: None,
            };
            let ni = self.nodes.len();
            self.nodes.push(node);
            if let Some(&(parent, _)) = stack.last() {
                self.nodes[parent].children.push(ni);
            } else {
                root = ni;
            }
            match se.num_children {
                Some(c) if c > 0 => {
                    stack.push((ni, c));
                }
                _ => {
                    self.nodes[ni].leaf = Some(leaf_count);
                    leaf_count += 1;
                    // pop finished parents
                    while let Some(&mut (p, ref mut rem)) = stack.last_mut() {
                        *rem -= 1;
                        if *rem == 0 {
                            stack.pop();
                        } else {
                            break;
                        }
                    }
                }
            }
            idx += 1;
        }
        if let Some(&(_, r)) = stack.last() {
            let _ = r;
            return Err(PqError::parquet("invalid schema"));
        }
        self.root = root;
        // compute max_def / max_rep and collect leaves in DFS order
        self.compute_levels(root, 0, 0);
        Ok(())
    }

    fn compute_levels(&mut self, ni: usize, def: i16, rep: i16) {
        let (mut d, mut r) = (def, rep);
        {
            let n = &mut self.nodes[ni];
            match n.repetition {
                REP_OPTIONAL => d += 1,
                REP_REPEATED => {
                    d += 1;
                    r += 1;
                }
                _ => {}
            }
            n.max_def = d;
            n.max_rep = r;
        }
        let kids = self.nodes[ni].children.clone();
        if kids.is_empty() {
            let path = self.path_of(ni);
            let li = self.nodes[ni].leaf.unwrap();
            self.leaves.push(Leaf { node: ni, path });
            let _ = li;
        } else {
            for k in kids {
                self.compute_levels(k, d, r);
            }
        }
    }

    fn path_of(&self, ni: usize) -> Vec<String> {
        let mut path = Vec::new();
        let mut cur = ni;
        while let Some(p) = self.parent_of(cur) {
            path.push(self.nodes[p].name.clone());
            cur = p;
        }
        path.reverse();
        path
    }

    fn parent_of(&self, ni: usize) -> Option<usize> {
        self.nodes.iter().position(|n| n.children.contains(&ni))
    }

    pub fn num_leaf_columns(&self) -> usize {
        self.leaves.len()
    }

    /// Read a whole row group: returns one Vec<Val> per top-level column.
    pub fn read_row_group(&self, rg_idx: usize) -> Result<Vec<Vec<Val>>, PqError> {
        let rg = &self.meta.row_groups[rg_idx];
        let mut leaf_vals: Vec<Vec<Val>> = Vec::with_capacity(self.leaves.len());
        let mut leaf_defs: Vec<Vec<i16>> = Vec::new();
        let mut leaf_reps: Vec<Vec<i16>> = Vec::new();
        for cc in &rg.columns {
            let md = match &cc.meta_data {
                Some(m) => m,
                None => {
                    return Err(PqError::parquet("column chunk without metadata"));
                }
            };
            let leaf_idx = self.find_leaf(&md.path_in_schema)?;
            let node = self.leaves[leaf_idx].node;
            let (defs, reps, vals) = self.read_column(md)?;
            let _ = node;
            leaf_defs.push(defs);
            leaf_reps.push(reps);
            leaf_vals.push(vals);
        }
        // Assemble top-level values
        let mut cols: Vec<Vec<Val>> = Vec::new();
        let top: Vec<usize> = self.nodes[self.root].children.clone();
        let mut li = 0usize;
        for &t in &top {
            let mut cur = ColCursor {
                leaf_defs: &leaf_defs,
                leaf_reps: &leaf_reps,
                leaf_vals: &leaf_vals,
                pos: vec![0usize; self.leaves.len()],
            };
            let vals = self.assemble_top(t, &mut cur, rg.num_rows as usize)?;
            let _ = &mut li;
            cols.push(vals);
        }
        Ok(cols)
    }

    fn find_leaf(&self, path: &[String]) -> Result<usize, PqError> {
        for (i, l) in self.leaves.iter().enumerate() {
            if l.path.len() == path.len() && l.path.iter().zip(path).all(|(a, b)| a == b) {
                return Ok(i);
            }
        }
        Err(PqError::parquet(format!(
            "column path not found in schema: {:?}",
            path
        )))
    }

    fn read_column(
        &self,
        md: &ColumnMetaData,
    ) -> Result<(Vec<i16>, Vec<i16>, Vec<Val>), PqError> {
        let leaf_idx = self.find_leaf(&md.path_in_schema)?;
        let node = self.leaves[leaf_idx].node;
        let max_def = self.nodes[node].max_def;
        let max_rep = self.nodes[node].max_rep;
        let ptype = md.ptype;
        let type_length = self.nodes[node].type_length;
        let mut dict: Option<Vec<Val>> = None;
        let mut defs: Vec<i16> = Vec::new();
        let mut reps: Vec<i16> = Vec::new();
        let mut vals: Vec<Val> = Vec::new();
        let mut pos = md.dictionary_page_offset.unwrap_or(md.data_page_offset) as usize;
        let data = &self.data;
        let total = md.num_values;
        let mut page_num = 0usize;
        loop {
            if pos + 4 > data.len() {
                break;
            }
            let (hdr_end, page_type, usize_comp, usize_unc, dph, dph2, dict_header) =
                decode::read_page_header(data, pos)?;
            let comp = usize_comp;
            if pos + hdr_end + comp > data.len() {
                return Err(PqError::parquet("page data out of bounds"));
            }
            let raw = &data[pos + hdr_end..pos + hdr_end + comp];
            let body = if md.codec == CODEC_UNCOMPRESSED {
                raw.to_vec()
            } else {
                let unc = compress::decompress(md.codec, raw, usize_unc)?;
                if unc.len() != usize_unc && usize_unc > 0 {
                    // tolerate
                }
                unc
            };
            let _ = usize_unc;
            match page_type {
                0 => {
                    // data page v1
                    let (nv, venc, def_enc, rep_enc) = dph;
                    let mut p = 0usize;
                    if max_rep > 0 {
                        let bw = level_bit_width(max_rep);
                        let lv = decode::decode_rle_levels(&body[p..], bw, nv)?;
                        p += bytes_used(&body[p..], bw, nv);
                        reps.extend(lv);
                    } else {
                        reps.extend(std::iter::repeat(0i16).take(nv));
                    }
                    if max_def > 0 {
                        let bw = level_bit_width(max_def);
                        let lv = decode::decode_rle_levels(&body[p..], bw, nv)?;
                        p += bytes_used(&body[p..], bw, nv);
                        defs.extend(lv);
                    } else {
                        defs.extend(std::iter::repeat(0i16).take(nv));
                    }
                    let nvals = if max_def > 0 {
                        defs[defs.len() - nv..]
                            .iter()
                            .filter(|&&d| d == max_def)
                            .count()
                    } else {
                        nv
                    };
                    let rawvals = decode::decode_values(
                        venc,
                        &body[p..],
                        nvals,
                        ptype,
                        type_length,
                        dict.as_ref(),
                    )?;
                    let conv = raw_to_vals(rawvals, self, node);
                    vals.extend(conv);
                }
                2 => {
                    let (nv, _enc) = dict_header;
                    let rawvals = decode::read_plain(ptype, &body, nv, type_length)?;
                    dict = Some(raw_to_vals(rawvals, self, node));
                }
                3 => {
                    let (nv, nn, nrv, venc, def_len, rep_len, _comp) = dph2;
                    let mut p = 0usize;
                    if max_rep > 0 {
                        let bw = level_bit_width(max_rep);
                        let lv = decode::decode_rle_levels(&body[p..p + rep_len], bw, nv)?;
                        p += rep_len;
                        reps.extend(lv);
                    } else {
                        reps.extend(std::iter::repeat(0i16).take(nv));
                        p += rep_len;
                    }
                    if max_def > 0 {
                        let bw = level_bit_width(max_def);
                        let lv = decode::decode_rle_levels(&body[p..p + def_len], bw, nv)?;
                        p += def_len;
                        defs.extend(lv);
                    } else {
                        defs.extend(std::iter::repeat(0i16).take(nv));
                        p += def_len;
                    }
                    let nvals = if max_def > 0 {
                        defs[defs.len() - nv..]
                            .iter()
                            .filter(|&&d| d == max_def)
                            .count()
                    } else {
                        nv
                    };
                    let rawvals = decode::decode_values(
                        venc,
                        &body[p..],
                        nvals,
                        ptype,
                        type_length,
                        dict.as_ref(),
                    )?;
                    let conv = raw_to_vals(rawvals, self, node);
                    vals.extend(conv);
                    let _ = nn;
                    let _ = nrv;
                }
                _ => {
                    // index page or unknown: skip
                }
            }
            pos += hdr_end + comp;
            page_num += 1;
            if vals.len() as i64 >= total || (max_def > 0 && defs.len() as i64 >= total) {
                break;
            }
            if page_num > 1_000_000 {
                break;
            }
        }
        Ok((defs, reps, vals))
    }

    /// Assemble the values of one top-level column for a row group.
    fn assemble_top(
        &self,
        node_idx: usize,
        cur: &mut ColCursor,
        rows: usize,
    ) -> Result<Vec<Val>, PqError> {
        let mut out = Vec::with_capacity(rows);
        for _ in 0..rows {
            let v = self.assemble_node(node_idx, cur)?;
            out.push(v.unwrap_or(Val::Null));
        }
        Ok(out)
    }

    fn assemble_node(&self, ni: usize, cur: &mut ColCursor) -> Result<Option<Val>, PqError> {
        let node = &self.nodes[ni];
        if node.children.is_empty() {
            // leaf
            let li = node.leaf.unwrap();
            let d = cur.def(li)?;
            let max_def = node.max_def;
            let v = if d == max_def {
                cur.take_val(li)
            } else {
                cur.advance(li);
                Val::Null
            };
            return Ok(Some(v));
        }
        let is_optional = node.repetition == REP_OPTIONAL;
        let is_repeated = node.repetition == REP_REPEATED;
        let first_leaf = self.first_leaf_of(ni);
        if is_optional {
            let li = first_leaf.ok_or_else(|| PqError::corrupt("group without leaves"))?;
            let d = cur.def(li)?;
            if d < node.max_def {
                // absent: consume one level entry for each leaf below
                self.consume_absent(ni, cur)?;
                return Ok(None);
            }
        }
        if is_repeated {
            // collect elements while rep >= max_rep of this node
            let mut elems: Vec<Val> = Vec::new();
            loop {
                let li = match self.first_leaf_of(ni) {
                    Some(l) => l,
                    None => break,
                };
                if !cur.has(li) {
                    break;
                }
                let r = cur.rep(li)?;
                if r < node.max_rep {
                    break;
                }
                // build one element
                let v = self.assemble_children(ni, cur)?;
                elems.push(v);
                // check if the next value continues this list
                let li2 = match self.first_leaf_of(ni) {
                    Some(l) => l,
                    None => break,
                };
                if !cur.has(li2) {
                    break;
                }
                let r2 = cur.rep(li2)?;
                if r2 < node.max_rep {
                    break;
                }
            }
            return Ok(Some(Val::List(elems)));
        }
        let v = self.assemble_children(ni, cur)?;
        Ok(Some(v))
    }

    /// Assemble the children of a group node into a Struct/List element value.
    fn assemble_children(&self, ni: usize, cur: &mut ColCursor) -> Result<Val, PqError> {
        let kids = self.nodes[ni].children.clone();
        let mut fields: Vec<Val> = Vec::with_capacity(kids.len());
        for k in kids {
            let v = self.assemble_node(k, cur)?;
            fields.push(v.unwrap_or(Val::Null));
        }
        // A group with a single child that is a LIST annotation group is a list
        if self.nodes[ni].is_list() && kids.len() == 1 {
            // pass through the list element
            return Ok(fields.into_iter().next().unwrap_or(Val::Null));
        }
        Ok(Val::Struct(fields))
    }

    fn consume_absent(&self, ni: usize, cur: &mut ColCursor) -> Result<(), PqError> {
        // The node is absent; consume one level entry per leaf below, but for
        // repeated descendants nothing is present (they are empty).
        for li in self.leaves_under(ni) {
            let d = cur.def(li)?;
            let _ = d;
            cur.advance(li);
        }
        Ok(())
    }

    fn leaves_under(&self, ni: usize) -> Vec<usize> {
        let mut out = Vec::new();
        let mut stack = vec![ni];
        while let Some(n) = stack.pop() {
            if self.nodes[n].children.is_empty() {
                if let Some(l) = self.nodes[n].leaf {
                    out.push(l);
                }
            } else {
                for &c in &self.nodes[n].children {
                    stack.push(c);
                }
            }
        }
        out.sort();
        out
    }

    fn first_leaf_of(&self, ni: usize) -> Option<usize> {
        let mut stack = vec![ni];
        while let Some(n) = stack.pop() {
            if self.nodes[n].children.is_empty() {
                return self.nodes[n].leaf;
            }
            for &c in self.nodes[n].children.iter().rev() {
                stack.push(c);
            }
        }
        None
    }
}

impl Node {
    pub fn is_list(&self) -> bool {
        if let Some(lt) = &self.logical {
            if lt.kind == 3 {
                return true;
            }
        }
        matches!(self.converted_type, Some(3))
    }
}

pub struct ColCursor<'a> {
    pub leaf_defs: &'a [Vec<i16>],
    pub leaf_reps: &'a [Vec<i16>],
    pub leaf_vals: &'a [Vec<Val>],
    pub pos: Vec<usize>,
}

impl<'a> ColCursor<'a> {
    pub fn has(&self, li: usize) -> bool {
        self.pos.get(li).map_or(false, |p| *p < self.leaf_defs[li].len())
    }
    pub fn def(&self, li: usize) -> Result<i16, PqError> {
        let p = *self.pos.get(li).unwrap_or(&0);
        self.leaf_defs
            .get(li)
            .and_then(|v| v.get(p))
            .copied()
            .ok_or_else(|| PqError::corrupt("def level out of range"))
    }
    pub fn rep(&self, li: usize) -> Result<i16, PqError> {
        let p = *self.pos.get(li).unwrap_or(&0);
        self.leaf_reps
            .get(li)
            .and_then(|v| v.get(p))
            .copied()
            .ok_or_else(|| PqError::corrupt("rep level out of range"))
    }
    pub fn advance(&mut self, li: usize) {
        if let Some(p) = self.pos.get_mut(li) {
            *p += 1;
        }
    }
    pub fn take_val(&mut self, li: usize) -> Val {
        let p = self.pos[li];
        self.pos[li] = p + 1;
        self.leaf_vals[li].get(p).cloned().unwrap_or(Val::Null)
    }
}

pub fn level_bit_width(max: i16) -> u8 {
    if max <= 0 {
        0
    } else {
        let mut w = 1u8;
        while (1i32 << w) <= max as i32 {
            w += 1;
        }
        w
    }
}

/// Number of bytes consumed by an RLE-encoded level stream of `n` values.
pub fn bytes_used(data: &[u8], bit_width: u8, n: usize) -> usize {
    if bit_width == 0 || n == 0 {
        return 0;
    }
    let mut br = decode::BitReader::new(data);
    let mut used = 0usize;
    let mut count = 0usize;
    while count < n {
        // read varint (8 bits at a time)
        let mut header: u64 = 0;
        let mut shift = 0u32;
        loop {
            match br.read_bits(8) {
                Ok(b) => {
                    used += 1;
                    header |= (b & 0x7f) << shift;
                    shift += 7;
                    if b & 0x80 == 0 {
                        break;
                    }
                }
                Err(_) => return used,
            }
        }
        if header & 1 == 0 {
            let c = (header >> 1) as usize;
            let bits = bit_width as usize;
            let _ = br.read_bits(bits);
            used += (bits + 7) / 8;
            count += c;
        } else {
            let c = (header >> 1) as usize * 8;
            let bits = bit_width as usize * c;
            let _ = br.read_bits(bits);
            used += (bits + 7) / 8;
            count += c;
        }
        if count > n + 8 {
            break;
        }
    }
    used
}

fn raw_to_vals(rv: decode::RawValues, pf: &ParquetFile, node: usize) -> Vec<Val> {
    let n = &pf.nodes[node];
    let scale = n.scale;
    let precision = n.precision;
    let is_string = n.logical.kind == 1
        || matches!(n.converted_type, Some(0))
        || (n.ptype == TYPE_BYTE_ARRAY && n.logical.kind == 0 && n.converted_type == Some(0));
    match rv {
        decode::RawValues::Int32(v) => v
            .into_iter()
            .map(|x| int32_to_val(x, n))
            .collect(),
        decode::RawValues::Int64(v) => v
            .into_iter()
            .map(|x| int64_to_val(x, n))
            .collect(),
        decode::RawValues::Int96(v) => v.into_iter().map(int96_to_val).collect(),
        decode::RawValues::Float(v) => v.into_iter().map(Val::F32).collect(),
        decode::RawValues::Double(v) => v.into_iter().map(Val::F64).collect(),
        decode::RawValues::ByteArray(v) => {
            if n.logical.kind == 5 {
                // decimal from byte array
                v.into_iter()
                    .map(|b| {
                        let unscaled = be_bytes_to_i128(&b);
                        Val::Decimal(unscaled, scale.max(0) as u32)
                    })
                    .collect()
            } else if is_string {
                v.into_iter()
                    .map(|b| Val::Str(String::from_utf8_lossy(&b).into_owned()))
                    .collect()
            } else {
                v.into_iter().map(Val::Bytes).collect()
            }
        }
        decode::RawValues::Bool(v) => v.into_iter().map(Val::Bool).collect(),
    }
}

fn int32_to_val(x: i32, n: &Node) -> Val {
    let lt = &n.logical;
    if n.logical.kind == 5 {
        return Val::Decimal(x as i128, n.scale.max(0) as u32);
    }
    if let Some(ct) = n.converted_type {
        match ct {
            6 => return Val::Date(x), // DATE
            9 => return Val::TsMillis(x as i64),
            10 => return Val::TsMicros(x as i64),
            _ => {}
        }
    }
    if lt.kind == 6 {
        return Val::Date(x);
    }
    if lt.kind == 8 {
        return match lt.unit {
            0 => Val::TsMillis(x as i64),
            1 => Val::TsMicros(x as i64),
            _ => Val::TsNanos(x as i64),
        };
    }
    if lt.kind == 7 {
        return match lt.unit {
            0 => Val::TimeMillis(x),
            1 => Val::TimeMicros(x as i64),
            _ => Val::TimeMicros(x as i64),
        };
    }
    if lt.kind == 9 {
        if lt.is_signed {
            return Val::I64(x as i64);
        }
        return Val::U64(x as u32 as u64);
    }
    if matches!(n.converted_type, Some(11..=14)) {
        return Val::U64(x as u32 as u64);
    }
    Val::I64(x as i64)
}

fn int64_to_val(x: i64, n: &Node) -> Val {
    let lt = &n.logical;
    if lt.kind == 5 {
        return Val::Decimal(x as i128, n.scale.max(0) as u32);
    }
    if let Some(ct) = n.converted_type {
        match ct {
            9 => return Val::TsMillis(x),
            10 => return Val::TsMicros(x),
            _ => {}
        }
    }
    if lt.kind == 8 {
        return match lt.unit {
            0 => Val::TsMillis(x),
            1 => Val::TsMicros(x),
            _ => Val::TsNanos(x),
        };
    }
    if lt.kind == 7 {
        return match lt.unit {
            0 => Val::TimeMillis(x as i32),
            _ => Val::TimeMicros(x),
        };
    }
    if lt.kind == 9 {
        if lt.is_signed {
            return Val::I64(x);
        }
        return Val::U64(x as u64);
    }
    if matches!(n.converted_type, Some(14)) {
        return Val::U64(x as u64);
    }
    Val::I64(x)
}

fn int96_to_val(w: [u32; 3]) -> Val {
    // 12 bytes: 8 bytes nanos-of-day (LE), 4 bytes julian day
    let nanos = (w[0] as u64) | ((w[1] as u64) << 32);
    let day = w[2] as i64;
    // julian day 2440588 == 1970-01-01
    let secs = (day - 2440588) * 86400;
    Val::TsNanos(secs * 1_000_000_000 + nanos as i64)
}

pub fn be_bytes_to_i128(b: &[u8]) -> i128 {
    if b.is_empty() {
        return 0;
    }
    let mut v: u128 = 0;
    for &x in b {
        v = (v << 8) | x as u128;
    }
    let bits = b.len() * 8;
    if bits < 128 {
        let sign = (v >> (bits - 1)) & 1;
        if sign == 1 {
            v |= (!0u128) << bits;
        }
    }
    v as i128
}
