                let l = lens[k] as usize;
                let b = r.read_bytes(l)?;
                out.push(b.to_vec());
            }
            Ok(RawValues::ByteArray(out))
        }
        9 => {
            // byte stream split
            let tl = if ptype == 6 {
                0
            } else {
                type_length as usize
            };
            let width = if ptype == 6 {
                // byte array: each value has a 4-byte length? BYTE_STREAM_SPLIT for byte array uses fixed width
                return Err(PqError::nyi("byte stream split for byte array"));
            } else {
                tl
            };
            let mut streams: Vec<&[u8]> = Vec::new();
            let w = width.max(1);
            for s in 0..w {
                let start = s * count;
                if start + count > data.len() {
                    return Err(PqError::Corrupt("byte stream split truncated".into()));
                }
                streams.push(&data[start..start + count]);
            }
            let mut out = Vec::with_capacity(count);
            for i in 0..count {
                let mut v = Vec::with_capacity(w);
                for s in 0..w {
                    v.push(streams[s][i]);
                }
                out.push(v);
            }
            Ok(RawValues::ByteArray(out))
        }
        3 | 4 => Err(PqError::Corrupt(
            "RLE/BIT_PACKED encoding is only valid for levels".into(),
        )),
        other => Err(PqError::Corrupt(format!("unsupported encoding {}", other))),
    }
}

