//! Minimal terminal UI: cell buffer, styles and a diff-based ANSI writer.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Reset,
    Indexed(u8),
    Rgb(u8, u8, u8),
}

pub const MOD_BOLD: u16 = 1 << 0;
pub const MOD_DIM: u16 = 1 << 1;
pub const MOD_ITALIC: u16 = 1 << 2;
pub const MOD_UNDERLINED: u16 = 1 << 3;
pub const MOD_SLOW_BLINK: u16 = 1 << 4;
pub const MOD_RAPID_BLINK: u16 = 1 << 5;
pub const MOD_REVERSED: u16 = 1 << 6;
pub const MOD_HIDDEN: u16 = 1 << 7;
pub const MOD_CROSSED_OUT: u16 = 1 << 8;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub underline: Option<Color>,
    pub add: u16,
    pub sub: u16,
}

impl Default for Style {
    fn default() -> Self {
        Style { fg: None, bg: None, underline: None, add: 0, sub: 0 }
    }
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }
    pub fn fg(mut self, c: Color) -> Style {
        self.fg = Some(c);
        self
    }
    pub fn bg(mut self, c: Color) -> Style {
        self.bg = Some(c);
        self
    }
    pub fn bold(mut self) -> Style {
        self.add |= MOD_BOLD;
        self
    }
    pub fn underlined(mut self) -> Style {
        self.add |= MOD_UNDERLINED;
        self
    }
    pub fn reversed(mut self) -> Style {
        self.add |= MOD_REVERSED;
        self
    }
    /// Combine: apply `other`'s attributes on top of self
    pub fn patch(mut self, other: Style) -> Style {
        if other.fg.is_some() {
            self.fg = other.fg;
        }
        if other.bg.is_some() {
            self.bg = other.bg;
        }
        if other.underline.is_some() {
            self.underline = other.underline;
        }
        self.add = (self.add & !other.sub) | other.add;
        self.sub = (self.sub & !other.add) | other.sub;
        self
    }
}

/// Cell holds a symbol plus the effective style.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Cell {
    pub sym: String,
    pub fg: Color,
    pub bg: Color,
    pub underline: Color,
    pub mods: u16,
}

impl Default for Cell {
    fn default() -> Self {
        Cell { sym: " ".into(), fg: Color::Reset, bg: Color::Reset, underline: Color::Reset, mods: 0 }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub w: u16,
    pub h: u16,
}

impl Rect {
    pub fn new(x: u16, y: u16, w: u16, h: u16) -> Rect {
        Rect { x, y, w, h }
    }
    pub fn right(&self) -> u16 {
        self.x + self.w
    }
    pub fn bottom(&self) -> u16 {
        self.y + self.h
    }
    pub fn is_empty(&self) -> bool {
        self.w == 0 || self.h == 0
    }
    pub fn inner(&self) -> Rect {
        Rect {
            x: self.x + 1,
            y: self.y + 1,
            w: self.w.saturating_sub(2),
            h: self.h.saturating_sub(2),
        }
    }
    /// Intersect with another rect
    pub fn intersect(&self, o: &Rect) -> Rect {
        let x = self.x.max(o.x);
        let y = self.y.max(o.y);
        let w = self.right().min(o.right()).saturating_sub(x);
        let h = self.bottom().min(o.bottom()).saturating_sub(y);
        Rect { x, y, w, h }
    }
}

pub struct Buffer {
    pub w: u16,
    pub h: u16,
    pub cells: Vec<Cell>,
}

impl Buffer {
    pub fn new(w: u16, h: u16) -> Buffer {
        Buffer { w, h, cells: vec![Cell::default(); w as usize * h as usize] }
    }
    pub fn reset(&mut self) {
        for c in self.cells.iter_mut() {
            *c = Cell::default();
        }
    }
    pub fn resize(&mut self, w: u16, h: u16) {
        self.w = w;
        self.h = h;
        self.cells = vec![Cell::default(); w as usize * h as usize];
    }
    pub fn idx(&self, x: u16, y: u16) -> usize {
        y as usize * self.w as usize + x as usize
    }
    pub fn set(&mut self, x: u16, y: u16, sym: &str, st: &Style) {
        if x >= self.w || y >= self.h {
            return;
        }
        let i = self.idx(x, y);
        let c = &mut self.cells[i];
        c.sym = sym.to_string();
        if let Some(f) = st.fg {
            c.fg = f;
        }
        if let Some(b) = st.bg {
            c.bg = b;
        }
        if let Some(u) = st.underline {
            c.underline = u;
        }
        c.mods = (c.mods & !st.sub) | st.add;
    }
    /// Write a string starting at (x,y); returns the number of cells written.
    pub fn set_string(&mut self, x: u16, y: u16, s: &str, st: &Style) -> u16 {
        let mut cx = x;
        for g in s.chars() {
            if cx >= self.w {
                break;
            }
            self.set(cx, y, &g.to_string(), st);
            cx += 1;
        }
        cx - x
    }
    pub fn set_style(&mut self, area: &Rect, st: &Style) {
        for y in area.y..area.bottom().min(self.h) {
            for x in area.x..area.right().min(self.w) {
                let c = &mut self.cells[self.idx(x, y)];
                if let Some(f) = st.fg {
                    c.fg = f;
                }
                if let Some(b) = st.bg {
                    c.bg = b;
                }
                if let Some(u) = st.underline {
                    c.underline = u;
                }
                c.mods = (c.mods & !st.sub) | st.add;
            }
        }
    }
    pub fn fill(&mut self, area: &Rect, sym: &str, st: &Style) {
        for y in area.y..area.bottom().min(self.h) {
            for x in area.x..area.right().min(self.w) {
                self.set(x, y, sym, st);
            }
        }
    }

    /// Compute the list of cells that changed since `other`.
    pub fn diff(&self, other: &Buffer) -> Vec<(u16, u16, Cell)> {
        let mut out = Vec::new();
        for i in 0..self.cells.len().min(other.cells.len()) {
            if self.cells[i] != other.cells[i] {
                let x = (i % self.w as usize) as u16;
                let y = (i / self.w as usize) as u16;
                out.push((x, y, self.cells[i].clone()));
            }
        }
        out
    }
}

pub struct Terminal {
    pub buf: Buffer,
    pub prev: Buffer,
    pub out: Vec<u8>,
}

impl Terminal {
    pub fn new(w: u16, h: u16) -> Terminal {
        Terminal { buf: Buffer::new(w, h), prev: Buffer::new(w, h), out: Vec::new() }
    }
    pub fn resize(&mut self, w: u16, h: u16) {
        self.buf.resize(w, h);
        self.prev.resize(w, h);
        // full redraw
        self.prev.reset();
        self.prev.cells = vec![Cell::default(); w as usize * h as usize];
    }
    /// Render the diff to the output buffer.
    pub fn flush(&mut self) {
        let updates = self.buf.diff(&self.prev);
        let mut fg = Color::Reset;
        let mut bg = Color::Reset;
        let mut underline = Color::Reset;
        let mut mods: u16 = 0;
        let mut last: Option<(u16, u16)> = None;
        for (x, y, cell) in updates {
            let contiguous = matches!(last, Some((lx, ly)) if x == lx + 1 && y == ly);
            if !contiguous {
                self.out
                    .extend_from_slice(format!("\x1b[{};{}H", y + 1, x + 1).as_bytes());
            }
            last = Some((x, y));
            if cell.mods != mods {
                self.write_mod_diff(mods, cell.mods);
                mods = cell.mods;
            }
            if cell.fg != fg || cell.bg != bg {
                let f = if cell.fg != fg { Some(cell.fg) } else { None };
                let b = if cell.bg != bg { Some(cell.bg) } else { None };
                self.write_colors(f, b);
                fg = cell.fg;
                bg = cell.bg;
            }
            if cell.underline != underline {
                self.write_underline(cell.underline);
                underline = cell.underline;
            }
            self.out.extend_from_slice(cell.sym.as_bytes());
        }
        self.out.extend_from_slice(b"\x1b[39m\x1b[49m\x1b[59m\x1b[0m");
        self.out.extend_from_slice(b"\x1b[?25l");
        std::mem::swap(&mut self.buf, &mut self.prev);
        self.buf.reset();
        // keep sizes in sync
        let (w, h) = (self.prev.w, self.prev.h);
        self.buf.resize(w, h);
    }
    fn write_mod_diff(&mut self, from: u16, to: u16) {
        let removed = from & !to;
        if removed & MOD_REVERSED != 0 {
            self.out.extend_from_slice(b"\x1b[27m");
        }
        if removed & MOD_BOLD != 0 {
            self.out.extend_from_slice(b"\x1b[22m");
            if to & MOD_DIM != 0 {
                self.out.extend_from_slice(b"\x1b[2m");
            }
        }
        if removed & MOD_ITALIC != 0 {
            self.out.extend_from_slice(b"\x1b[23m");
        }
        if removed & MOD_UNDERLINED != 0 {
            self.out.extend_from_slice(b"\x1b[24m");
        }
        if removed & MOD_DIM != 0 {
            self.out.extend_from_slice(b"\x1b[22m");
        }
        if removed & MOD_CROSSED_OUT != 0 {
            self.out.extend_from_slice(b"\x1b[29m");
        }
        if removed & (MOD_SLOW_BLINK | MOD_RAPID_BLINK) != 0 {
            self.out.extend_from_slice(b"\x1b[25m");
        }
        let added = to & !from;
        if added & MOD_REVERSED != 0 {
            self.out.extend_from_slice(b"\x1b[7m");
        }
        if added & MOD_BOLD != 0 {
            self.out.extend_from_slice(b"\x1b[1m");
        }
        if added & MOD_ITALIC != 0 {
            self.out.extend_from_slice(b"\x1b[3m");
        }
        if added & MOD_UNDERLINED != 0 {
            self.out.extend_from_slice(b"\x1b[4m");
        }
        if added & MOD_DIM != 0 {
            self.out.extend_from_slice(b"\x1b[2m");
        }
        if added & MOD_CROSSED_OUT != 0 {
            self.out.extend_from_slice(b"\x1b[9m");
        }
        if added & MOD_SLOW_BLINK != 0 {
            self.out.extend_from_slice(b"\x1b[5m");
        }
        if added & MOD_RAPID_BLINK != 0 {
            self.out.extend_from_slice(b"\x1b[6m");
        }
    }
    fn color_seq(c: Color, fg: bool) -> String {
        match c {
            Color::Reset => {
                if fg {
                    "39".into()
                } else {
                    "49".into()
                }
            }
            Color::Indexed(i) => {
                if fg {
                    format!("38;5;{}", i)
                } else {
                    format!("48;5;{}", i)
                }
            }
            Color::Rgb(r, g, b) => {
                if fg {
                    format!("38;2;{};{};{}", r, g, b)
                } else {
                    format!("48;2;{};{};{}", r, g, b)
                }
            }
        }
    }
    fn write_colors(&mut self, f: Option<Color>, b: Option<Color>) {
        match (f, b) {
            (Some(fg), Some(bg)) => {
                let s = format!("\x1b[{};{}m", Self::color_seq(fg, true), Self::color_seq(bg, false));
                self.out.extend_from_slice(s.as_bytes());
            }
            (Some(fg), None) => {
                let s = format!("\x1b[{}m", Self::color_seq(fg, true));
                self.out.extend_from_slice(s.as_bytes());
            }
            (None, Some(bg)) => {
                let s = format!("\x1b[{}m", Self::color_seq(bg, false));
                self.out.extend_from_slice(s.as_bytes());
            }
            (None, None) => {}
        }
    }
    fn write_underline(&mut self, c: Color) {
        let s = match c {
            Color::Reset => "\x1b[59m".to_string(),
            Color::Indexed(i) => format!("\x1b[58;5;{}m", i),
            Color::Rgb(r, g, b) => format!("\x1b[58;2;{};{};{}m", r, g, b),
        };
        self.out.extend_from_slice(s.as_bytes());
    }
}
EOF
