//! Widgets used by the app: blocks with borders/titles, text lines.

use super::{Buffer, Color, Rect, Style};

pub const HORIZONTAL: &str = "\u{2500}";
pub const VERTICAL: &str = "\u{2502}";
pub const TOP_LEFT: &str = "\u{256d}";
pub const TOP_RIGHT: &str = "\u{256e}";
pub const BOTTOM_LEFT: &str = "\u{2570}";
pub const BOTTOM_RIGHT: &str = "\u{256f}";
pub const TEE_RIGHT: &str = "\u{252c}";
pub const TEE_LEFT: &str = "\u{2534}";
pub const TEE_DOWN: &str = "\u{253c}";
pub const TEE_UP: &str = "\u{2534}";

pub struct BorderSet {
    pub top_left: &'static str,
    pub top_right: &'static str,
    pub bottom_left: &'static str,
    pub bottom_right: &'static str,
    pub horizontal: &'static str,
    pub vertical: &'static str,
}

impl Default for BorderSet {
    fn default() -> Self {
        BorderSet {
            top_left: TOP_LEFT,
            top_right: TOP_RIGHT,
            bottom_left: BOTTOM_LEFT,
            bottom_right: BOTTOM_RIGHT,
            horizontal: HORIZONTAL,
            vertical: VERTICAL,
        }
    }
}

pub const PLAIN_SET: BorderSet = BorderSet {
    top_left: "\u{250c}",
    top_right: "\u{2510}",
    bottom_left: "\u{2514}",
    bottom_right: "\u{2518}",
    horizontal: HORIZONTAL,
    vertical: VERTICAL,
};

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Borders(pub u8);
impl Borders {
    pub const NONE: Borders = Borders(0);
    pub const TOP: Borders = Borders(1);
    pub const RIGHT: Borders = Borders(2);
    pub const BOTTOM: Borders = Borders(4);
    pub const LEFT: Borders = Borders(8);
    pub const ALL: Borders = Borders(15);
    pub fn contains(&self, o: Borders) -> bool {
        self.0 & o.0 == o.0
    }
}

pub struct Title<'a> {
    pub text: Vec<(&'a str, Style)>,
    pub alignment: u8, // 0 left, 1 center, 2 right
    pub position: u8,  // 0 top, 1 bottom
}

impl<'a> Title<'a> {
    pub fn new(text: &'a str, st: Style) -> Title<'a> {
        Title { text: vec![(text, st)], alignment: 0, position: 0 }
    }
    pub fn centered(text: &'a str, st: Style) -> Title<'a> {
        Title { text: vec![(text, st)], alignment: 1, position: 0 }
    }
    pub fn width(&self) -> usize {
        self.text.iter().map(|(t, _)| t.chars().count()).sum()
    }
}

/// Draw a block with borders and titles.
pub fn block(
    buf: &mut Buffer,
    area: &Rect,
    borders: Borders,
    style: &Style,
    set: &BorderSet,
    titles: &[Title],
) {
    if area.is_empty() {
        return;
    }
    if borders.contains(Borders::LEFT) {
        for y in area.y..area.bottom() {
            buf.set(area.x, y, set.vertical, style);
        }
    }
    if borders.contains(Borders::TOP) {
        for x in area.x..area.right() {
            buf.set(x, area.y, set.horizontal, style);
        }
    }
    if borders.contains(Borders::RIGHT) {
        for y in area.y..area.bottom() {
            buf.set(area.right() - 1, y, set.vertical, style);
        }
    }
    if borders.contains(Borders::BOTTOM) {
        for x in area.x..area.right() {
            buf.set(x, area.bottom() - 1, set.horizontal, style);
        }
    }
    // corners
    if borders.contains(Borders::TOP | Borders::LEFT) {
        buf.set(area.x, area.y, set.top_left, style);
    }
    if borders.contains(Borders::TOP | Borders::RIGHT) {
        buf.set(area.right() - 1, area.y, set.top_right, style);
    }
    if borders.contains(Borders::BOTTOM | Borders::LEFT) {
        buf.set(area.x, area.bottom() - 1, set.bottom_left, style);
    }
    if borders.contains(Borders::BOTTOM | Borders::RIGHT) {
        buf.set(area.right() - 1, area.bottom() - 1, set.bottom_right, style);
    }
    // titles
    for t in titles {
        let (y, inner_x, inner_w) = if t.position == 0 {
            (area.y, area.x + 1, area.w.saturating_sub(2))
        } else {
            (area.bottom().saturating_sub(1), area.x + 1, area.w.saturating_sub(2))
        };
        if inner_w == 0 {
            continue;
        }
        let tw = t.width() as u16;
        let x = match t.alignment {
            0 => inner_x,
            1 => inner_x + (inner_w.saturating_sub(tw)) / 2,
            _ => inner_x + inner_w.saturating_sub(tw),
        };
        let mut cx = x;
        for (txt, st) in &t.text {
            for ch in txt.chars() {
                if cx >= area.right() - 1 && t.position == 0 && borders.contains(Borders::RIGHT) {
                    break;
                }
                buf.set(cx, y, &ch.to_string(), st);
                cx += 1;
            }
        }
    }
}

