//! Value formatting helpers matching the reference tool's output.

use pq::values::Val;

pub fn fmt_bool(b: bool) -> String {
    if b { "true".into() } else { "false".into() }
}

/// Format a byte slice the way Rust's `{:?}` does for `&[u8]`.
pub fn fmt_bytes(b: &[u8]) -> String {
    let mut s = String::from("b\"");
    for &c in b {
        match c {
            b'"' => s.push_str("\\\""),
            b'\\' => s.push_str("\\\\"),
            0x20..=0x7e => s.push(c as char),
            _ => s.push_str(&format!("\\x{:02x}", c)),
        }
    }
    s.push('"');
    s
}

/// Format a float like Rust's Display for f64/f32.
pub fn fmt_float_f64(v: f64) -> String {
    if v.is_nan() {
        return "NaN".into();
    }
    if v.is_infinite() {
        return if v > 0.0 { "inf".into() } else { "-inf".into() };
    }
    format!("{}", v)
}

pub fn fmt_float_f32(v: f32) -> String {
    if v.is_nan() {
        return "NaN".into();
    }
    if v.is_infinite() {
        return if v > 0.0 { "inf".into() } else { "-inf".into() };
    }
    format!("{}", v)
}

/// Decimal point number with the given scale (e.g. 100, 2 -> "1.00")
pub fn fmt_decimal(unscaled: i128, scale: u32) -> String {
    let neg = unscaled < 0;
    let mut digits = unscaled.unsigned_abs().to_string();
    if scale == 0 {
        if neg {
            return format!("-{}", digits);
        }
        return digits;
    }
    let scale = scale as usize;
    while digits.len() <= scale {
        digits.insert(0, '0');
    }
    let split = digits.len() - scale;
    let out = format!("{}.{}", &digits[..split], &digits[split..]);
    if neg {
        format!("-{}", out)
    } else {
        out
    }
}

/// Insert thousands separators.
pub fn fmt_thousands(n: i64) -> String {
    if n < 0 {
        return format!("-{}", fmt_thousands(-n));
    }
    let s = n.to_string();
    let mut out = String::new();
    let bytes = s.as_bytes();
    for (i, c) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(*c as char);
    }
    out
}

/// Size in human readable form used in the metadata tab: "532 B", "316.00 KiB"
pub fn fmt_size_kib(n: i64) -> String {
    if n < 1024 {
        return format!("{} B", n);
    }
    let units = ["KiB", "MiB", "GiB", "TiB", "PiB"];
    let mut v = n as f64;
    let mut i = 0usize;
    while v >= 1024.0 && i < units.len() - 1 {
        v /= 1024.0;
        i += 1;
    }
    format!("{:.2} {}", v, units[i])
}

/// Size in human readable form used in the statistics table: "42 B", "8.1 KB"
pub fn fmt_size_kb(n: i64) -> String {
    if n < 1024 {
        return format!("{} B", n);
    }
    let units = ["KB", "MB", "GB", "TB"];
    let mut v = n as f64;
    let mut i = 0usize;
    while v >= 1024.0 && i < units.len() - 1 {
        v /= 1024.0;
        i += 1;
    }
    format!("{:.1} {}", v, units[i])
}

/// Size used for chart axis labels: "355.5K"
pub fn fmt_size_chart(n: f64) -> String {
    let units = ["", "K", "M", "G", "T"];
    let mut v = n;
    let mut i = 0usize;
    while v >= 1000.0 && i < units.len() - 1 {
        v /= 1000.0;
        i += 1;
    }
    if i == 0 {
        if v == v.trunc() {
            return format!("{}", v as i64);
        }
        return format!("{:.1}", v);
    }
    format!("{:.1}{}", v, units[i])
}

pub fn fmt_ratio(r: f64) -> String {
    format!("{:.2}x", r)
}

const DAYS_IN_MONTH: [i64; 12] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

/// Convert a Unix timestamp (seconds) to (year, month, day, hour, min, sec)
pub fn civil_from_days(z0: i64) -> (i64, u32, u32) {
    let z = z0 + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as i64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m as u32, d as u32)
}

pub fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 } as i64;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn fmt_datetime(total_nanos: i64) -> String {
    let secs = total_nanos.div_euclid(1_000_000_000);
    let nanos = total_nanos.rem_euclid(1_000_000_000);
    let (y, mo, d) = civil_from_days(secs.div_euclid(86400));
    let sec_of_day = secs.rem_euclid(86400);
    let hh = sec_of_day / 3600;
    let mm = (sec_of_day % 3600) / 60;
    let ss = sec_of_day % 60;
    let mut out = format!(
        "{:04}-{:02}-{:02} {:02}:{:02}:{:02}",
        y, mo, d, hh, mm, ss
    );
    if nanos != 0 {
        let frac = format!("{:09}", nanos);
        let trimmed = frac.trim_end_matches('0');
        out.push('.');
        out.push_str(trimmed);
    }
    out
}

pub fn fmt_date(days: i32) -> String {
    let (y, m, d) = civil_from_days(days as i64);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

pub fn fmt_time_micros(v: i64) -> String {
    let total = v;
    let hh = total / 3_600_000_000;
    let mm = (total / 60_000_000) % 60;
    let ss = (total / 1_000_000) % 60;
    let micros = total % 1_000_000;
    let mut out = format!("{:02}:{:02}:{:02}", hh, mm, ss);
    if micros != 0 {
        out.push_str(&format!(".{:06}", micros).trim_end_matches('0'));
    }
    out
}

pub fn fmt_time_millis(v: i32) -> String {
    let hh = v / 3_600_000;
    let mm = (v / 60_000) % 60;
    let ss = (v / 1000) % 60;
    let ms = v % 1000;
    let mut out = format!("{:02}:{:02}:{:02}", hh, mm, ss);
    if ms != 0 {
        out.push_str(&format!(".{:03}", ms).trim_end_matches('0'));
    }
    out
}

pub fn fmt_val(v: &Val) -> String {
    match v {
        Val::Null => "NULL".into(),
        Val::Bool(b) => fmt_bool(*b),
        Val::I64(i) => format!("{}", i),
        Val::U64(u) => format!("{}", u),
        Val::F32(f) => fmt_float_f32(*f),
        Val::F64(f) => fmt_float_f64(*f),
        Val::Str(s) => format!("\"{}\"", s),
        Val::Bytes(b) => fmt_bytes(b),
        Val::TsMillis(ms) => fmt_datetime(*ms * 1_000_000),
        Val::TsMicros(us) => fmt_datetime(*us * 1000),
        Val::TsNanos(ns) => fmt_datetime(*ns),
        Val::Date(d) => fmt_date(*d),
        Val::TimeMillis(t) => fmt_time_millis(*t),
        Val::TimeMicros(t) => fmt_time_micros(*t),
        Val::Decimal(unscaled, scale) => fmt_decimal(*unscaled, *scale),
        Val::List(items) => {
            let inner: Vec<String> = items.iter().map(fmt_val).collect();
            format!("[{}]", inner.join(", "))
        }
        Val::Struct(items) => {
            let inner: Vec<String> = items.iter().map(fmt_val).collect();
            format!("{{{}}}", inner.join(","))
        }
    }
}

/// Truncate a value string for nested display.
pub fn truncate_nested(s: &str, max: usize) -> String {
    let chars: Vec<char> = s.chars().collect();
    if chars.len() > max {
        let mut out: String = chars[..max - 1].iter().collect();
        out.push('\u{2026}');
        out
    } else {
        s.to_string()
    }
}
EOF
echo ok"}

