//! Application state and rendering for the four tabs.

use crate::fmt;
use crate::pq::{self, values::Val, ParquetFile};
use crate::tui::widgets::*;
use crate::tui::{Buffer, Color, Rect, Style, Terminal};

pub const COL_HEADER: Color = Color::Indexed(3); // yellow
pub const COL_BORDER: Color = Color::Indexed(11); // light yellow
pub const COL_GUTTER: Color = Color::Indexed(8); // dark gray
pub const COL_PATH: Color = Color::Indexed(2); // green
pub const COL_BLUE: Color = Color::Indexed(4);
pub const COL_WHITE: Color = Color::Indexed(15);
pub const COL_GREEN: Color = Color::Indexed(2);
pub const COL_BLACK: Color = Color::Indexed(0);
pub const COL_GRAY: Color = Color::Indexed(7);
pub const COL_LIGHTBLUE: Color = Color::Indexed(12);
pub const COL_LIGHTCYAN: Color = Color::Indexed(14);
pub const COL_LIGHTMAGENTA: Color = Color::Indexed(13);
pub const COL_LIGHTRED: Color = Color::Indexed(9);
pub const HL_BG: Color = Color::Rgb(60, 60, 60);

pub const GUTTER_W: u16 = 6;
pub const DATA_X: u16 = 9;

pub struct ColumnStat {
    pub path: Vec<String>,
    pub ptype: i32,
    pub repetition: i32,
    pub codec: i32,
    pub encodings: Vec<i32>,
    pub compressed: i64,
    pub uncompressed: i64,
    pub num_values: i64,
    pub null_count: Option<i64>,
    pub min: Option<Vec<u8>>,
    pub max: Option<Vec<u8>>,
    pub has_stats: bool,
}

pub struct App {
    pub pf: ParquetFile,
    pub path: String,
    pub tab: usize,
    pub quitted: bool,
    // data
    pub columns: Vec<Vec<String>>, // [column][row]
    pub col_names: Vec<String>,
    pub col_widths: Vec<usize>,
    pub cum: Vec<usize>,
    pub total_rows: usize,
    pub row_groups_rows: Vec<usize>,
    pub rg_boundaries: Vec<usize>,
    // stats per leaf
    pub stats: Vec<ColumnStat>,
    // visualize state
    pub v_off: usize,
    pub v_sel: usize,
    pub v_col: usize,
    // schema state
    pub s_sel: Option<usize>,
    pub s_off: usize,
    pub s_hoff: usize,
    // row groups state
    pub rg_idx: usize,
    pub rg_sel: Option<usize>,
    pub rg_off: usize,
    pub rg_soff: usize,
}

impl App {
    pub fn new(pf: ParquetFile, path: String) -> Result<App, pq::error::PqError> {
        let total_rows = pf.meta.num_rows as usize;
        let mut columns: Vec<Vec<String>> = Vec::new();
        let mut rg_boundaries = Vec::new();
        for (i, _rg) in pf.meta.row_groups.iter().enumerate() {
            rg_boundaries.push(columns.first().map_or(0, |c| c.len()));
            let cols = pf.read_row_group(i)?;
            if columns.is_empty() {
                for _ in 0..cols.len() {
                    columns.push(Vec::new());
                }
            }
            for (ci, c) in cols.iter().enumerate() {
                if ci < columns.len() {
                    for v in c {
                        columns[ci].push(fmt::fmt_val(v));
                    }
                }
            }
        }
        let top: Vec<usize> = pf.nodes[pf.root].children.clone();
        let col_names: Vec<String> = top.iter().map(|&t| pf.nodes[t].name.clone()).collect();
        // column widths
        let mut col_widths = Vec::with_capacity(col_names.len());
        for (i, name) in col_names.iter().enumerate() {
            let mut mx = fmt::text_width(name);
            if let Some(c) = columns.get(i) {
                for v in c {
                    mx = mx.max(fmt::text_width(v));
                }
            }
            col_widths.push((10usize).max(mx + 2));
        }
        let mut cum = vec![0usize];
        for w in &col_widths {
            cum.push(cum.last().unwrap() + w);
        }
        let mut stats = Vec::new();
        for cc in pf.meta.row_groups.first().map_or(&Vec::new(), |r| &r.columns) {
            if let Some(md) = &cc.meta_data {
                let st = md.statistics.as_ref();
                stats.push(ColumnStat {
                    path: md.path_in_schema.clone(),
                    ptype: md.ptype,
                    repetition: pf
                        .nodes
                        .get(pf.leaf_node_of(&md.path_in_schema))
                        .map_or(0, |n| n.repetition),
                    codec: md.codec,
                    encodings: md.encodings.clone(),
                    compressed: md.total_compressed_size,
                    uncompressed: md.total_uncompressed_size,
                    num_values: md.num_values,
                    null_count: st.and_then(|s| s.null_count),
                    min: st.and_then(|s| s.min_value.clone().or_else(|| s.min.clone())),
                    max: st.and_then(|s| s.max_value.clone().or_else(|| s.max.clone())),
                    has_stats: st.is_some(),
                });
            }
        }
        Ok(App {
            pf,
            path,
            tab: 0,
            quitted: false,
            columns,
            col_names,
            col_widths,
            cum,
            total_rows,
            row_groups_rows: Vec::new(),
            rg_boundaries,
            stats,
            v_off: 0,
            v_sel: 0,
            v_col: 0,
            s_sel: None,
            s_off: 0,
            s_hoff: 0,
            rg_idx: 0,
            rg_sel: None,
            rg_off: 0,
            rg_soff: 0,
        })
    }

    pub fn visible_rows(&self, area_h: u16) -> usize {
        (area_h as usize).saturating_sub(1) // header row
    }

    /// Max scroll offset for the row view
    fn max_v_off(&self, area_h: u16) -> usize {
        let vis = self.visible_rows(area_h);
        self.total_rows.saturating_sub(vis)
    }

    pub fn scroll_rows(&mut self, area_h: u16, delta: i64) {
        let vis = self.visible_rows(area_h);
        if vis == 0 {
            return;
        }
        let max_sel = self.total_rows.saturating_sub(1);
        let ns = if delta > 0 {
            (self.v_sel + delta as usize).min(max_sel)
        } else {
            self.v_sel.saturating_sub((-delta) as usize)
        };
        self.v_sel = ns;
        // keep the selection visible with a margin of 2 at the bottom
        if self.v_sel > self.v_off + vis.saturating_sub(2) {
            self.v_off = self.v_sel + 2 - vis;
        }
        if self.v_sel < self.v_off {
            self.v_off = self.v_sel;
        }
        let mo = self.max_v_off(area_h);
        if self.v_off > mo {
            self.v_off = mo;
        }
    }

    pub fn scroll_cols(&mut self, area_w: u16, delta: i64) {
        let avail = (area_w as usize).saturating_sub(DATA_X as usize);
        let total: usize = self.cum.last().copied().unwrap_or(0);
        let n = self.col_widths.len();
        let max_off = if total > avail {
            // largest k with cum[k] <= total - avail
            let mut k = 0usize;
            while k + 1 < n && self.cum[k + 1] + avail <= total {
                k += 1;
            }
            k
        } else {
            0
        };
        let _ = avail;
        let _ = total;
        self.v_col = if delta > 0 {
            (self.v_col + delta as usize).min(max_off)
        } else {
            self.v_col.saturating_sub((-delta) as usize)
        };
    }
}
EOF
