{"command": "cat > /workspace/src/render.rs <<'EOF'
//! Rendering of the four tabs.

use crate::app::*;
use crate::fmt;
use crate::pq;
use crate::tui::widgets::*;
use crate::tui::{Buffer, Color, Rect, Style};

fn st_fg(c: Color) -> Style {
    Style::new().fg(c)
}

const TAB_NAMES: [&str; 4] = ["Visualize", "Metadata", "Schema", "Row Groups"];

pub fn render_header(app: &App, buf: &mut Buffer, area: &Rect) {
    if area.is_empty() {
        return;
    }
    let borders = Borders::ALL;
    let style = st_fg(COL_BORDER);
    block(buf, area, borders, &style, &BorderSet::default(), &[]);
    // tabs
    let inner_x = area.x + 1;
    let mut cx = inner_x;
    for (i, name) in TAB_NAMES.iter().enumerate() {
        // leading padding space
        buf.set(cx, area.y + 1, " ", &Style::default());
        cx += 1;
        let st = if i == app.tab {
            Style::new().reversed()
        } else {
            Style::default()
        };
        for ch in name.chars() {
            if cx >= area.right() - 1 {
                break;
            }
            buf.set(cx, area.y + 1, &ch.to_string(), &st);
            cx += 1;
        }
        buf.set(cx, area.y + 1, " ", &Style::default());
        cx += 1;
        buf.set(cx, area.y + 1, " ", &Style::default());
        cx += 1;
    }
    // file path, right aligned
    let pw = fmt::text_width(&app.path) as u16;
    let px = area.right().saturating_sub(1).saturating_sub(pw);
    if pw > 0 && px > area.x {
        let _ = buf.set_string(px, area.y + 1, &app.path, &st_fg(COL_PATH));
    }
}

pub struct FooterHint {
    pub spans: Vec<(String, Style)>,
}

fn key_pair(a: &str, b: &str, tail: &str) -> Vec<(String, Style)> {
    let mut v = Vec::new();
    v.push((a.to_string(), st_fg(COL_GREEN)));
    v.push(("/".to_string(), st_fg(COL_WHITE)));
    v.push((b.to_string(), st_fg(COL_BLUE)));
    v.push((tail.to_string(), Style::default()));
    v
}

fn sep(s: &str) -> Vec<(String, Style)> {
    vec![(s.to_string(), st_fg(COL_WHITE))]
}

fn plain(s: &str) -> Vec<(String, Style)> {
    vec![(s.to_string(), Style::default())]
}

pub fn footer_spans(app: &App) -> Vec<(String, Style)> {
    let mut v: Vec<(String, Style)> = Vec::new();
    match app.tab {
        0 => {
            v.extend(key_pair("\u{2191}", "\u{2193}", " : Row"));
            v.extend(sep(" | "));
            v.extend(key_pair("\u{2192}", "\u{2190}", " : Column"));
            v.extend(sep(" | "));
            v.extend(key_pair("u", "d", " : Page - "));
            v.push(("[Tab]".to_string(), st_fg(COL_GREEN)));
            v.extend(plain(" Next Tab, "));
            v.push(("[Q]".to_string(), st_fg(COL_BLUE)));
            v.extend(plain("uit"));
        }
        1 => {
            v.push(("[Tab]".to_string(), st_fg(COL_GREEN)));
            v.extend(plain(" Next Tab, "));
            v.push(("[Q]".to_string(), st_fg(COL_BLUE)));
            v.extend(plain("uit"));
        }
        2 | 3 => {
            if app.tab == 3 {
                v.extend(key_pair("\u{2192}", "\u{2190}", " : Iterate Row Groups, "));
            } else {
                v.extend(key_pair("\u{2190}", "\u{2192}", " : Scroll, "));
            }
            v.extend(key_pair("\u{2191}", "\u{2193}", " : Schema - "));
            v.push(("[Tab]".to_string(), st_fg(COL_GREEN)));
            v.extend(plain(" Next Tab, "));
            v.push(("[Q]".to_string(), st_fg(COL_BLUE)));
            v.extend(plain("uit"));
        }
        _ => {}
    }
    v
}

pub fn render_footer(app: &App, buf: &mut Buffer, area: &Rect) {
    if area.is_empty() {
        return;
    }
    let y = area.y;
    let mut spans: Vec<(String, Style)> = Vec::new();
    spans.push(("parqeye".to_string(), Style::new().bold().fg(COL_GREEN)));
    let hints = footer_spans(app);
    let hints_len: usize = hints.iter().map(|(s, _)| fmt::text_width(s)).sum();
    let gap = (area.w as usize).saturating_sub(7 + hints_len);
    if gap > 0 {
        spans.push((" ".repeat(gap).to_string(), Style::default()));
    }
    spans.extend(hints);
    let mut cx = area.x;
    for (s, st) in &spans {
        for ch in s.chars() {
            if cx >= area.right() {
                return;
            }
            buf.set(cx, y, &ch.to_string(), st);
            cx += 1;
        }
    }
}

pub fn render(app: &App, term: &mut Terminal) {
    let w = term.buf.w;
    let h = term.buf.h;
    let header = Rect::new(0, 0, w, 3);
    render_header(app, &mut term.buf, &header);
    if h <= 4 {
        return;
    }
    let footer_y = h - 1;
    let content = Rect::new(0, 3, w, h - 4);
    match app.tab {
        0 => render_visualize(app, &mut term.buf, &content),
        1 => render_metadata(app, &mut term.buf, &content),
        2 => render_schema(app, &mut term.buf, &content),
        _ => render_row_groups(app, &mut term.buf, &content),
    }
    render_footer(
        app,
        &mut term.buf,
        &Rect::new(0, footer_y, w, 1),
    );
}

// ---------------- Visualize ----------------

pub fn render_visualize(app: &App, buf: &mut Buffer, area: &Rect) {
    if area.is_empty() {
        return;
    }
    let w = area.w;
    // header row: column names
    let hdr_y = area.y;
    let mut i = app.v_col;
    let mut x = DATA_X;
    let mut drawn = 0u16;
    while i < app.col_names.len() {
        let wpx = app.col_widths[i] as u16;
        if x >= area.right() {
            break;
        }
        let name = &app.col_names[i];
        let _ = buf.set_string(x, hdr_y, name, &Style::new().bold().fg(COL_HEADER));
        drawn += wpx;
        x += wpx;
        i += 1;
    }
    // separator line
    let sep_y = area.y + 1;
    for cx in 0..w {
        let sym = if cx == GUTTER_W { TEE_RIGHT } else { HORIZONTAL };
        buf.set(area.x + cx, sep_y, sym, &st_fg(COL_GUTTER));
    }
    // rows
    let vis = area.h as usize - 1;
    let hl_style = Style::new().bold().fg(COL_WHITE).bg(HL_BG);
    for r in 0..vis {
        let row_idx = app.v_off + r;
        if row_idx >= app.total_rows {
            break;
        }
        let y = area.y + 2 + r as u16;
        let selected = row_idx == app.v_sel;
        // row number
        let num = (row_idx + 1).to_string();
        let num_style = if selected {
            Style::new().bold().underlined().fg(COL_GUTTER)
        } else {
            st_fg(COL_GUTTER)
        };
        let _ = buf.set_string(area.x, y, &num, &num_style);
        buf.set(area.x + GUTTER_W, y, VERTICAL, &st_fg(COL_GUTTER));
        // cells
        if selected {
            let rx = area.x + DATA_X;
            let rw = area.right().saturating_sub(rx);
            buf.set_style(&Rect::new(rx, y, rw, 1), &hl_style);
        }
        let mut ci = app.v_col;
        let mut x = DATA_X;
        while ci < app.col_names.len() {
            let wpx = app.col_widths[ci] as u16;
            if x >= area.right() {
                break;
            }
            let val = app
                .columns
                .get(ci)
                .and_then(|c| c.get(row_idx))
                .map(|s| s.as_str())
                .unwrap_or("");
            let _ = buf.set_string(area.x + x, y, val, &Style::default());
            x += wpx;
            ci += 1;
        }
    }
}

// ---------------- Metadata ----------------

pub fn metadata_rows(app: &App) -> Vec<(String, String)> {
    let fm = &app.pf.meta;
    let mut codecs: Vec<(i32, usize)> = Vec::new();
    let mut encs: Vec<i32> = Vec::new();
    let mut raw: i64 = 0;
    let mut comp: i64 = 0;
    for rg in &fm.row_groups {
        for cc in &rg.columns {
            if let Some(md) = &cc.meta_data {
                raw += md.total_uncompressed_size;
                comp += md.total_compressed_size;
                match codecs.iter_mut().find(|(c, _)| *c == md.codec) {
                    Some(e) => e.1 += 1,
                    None => codecs.push((md.codec, 1)),
                }
                for e in &md.encodings {
                    if !encs.contains(e) {
                        encs.push(*e);
                    }
                }
            }
        }
    }
    codecs.sort_by_key(|(c, _)| codec_name(*c).to_string());
    encs.sort();
    encs.dedup();
    let codecs_str = codecs
        .iter()
        .map(|(c, n)| format!("{}({})", codec_name(*c), n))
        .collect::<Vec<_>>()
        .join(", ");
    let encs_str = encs
        .iter()
        .map(|e| enc_name(*e).to_string())
        .collect::<Vec<_>>()
        .join(", ");
    let ratio = if raw > 0 && comp > 0 {
        raw as f64 / comp as f64
    } else {
        1.0
    };
    let avg = if fm.num_rows > 0 { raw / fm.num_rows } else { 0 };
    vec![
        ("Format version".into(), format!("{}", fm.version)),
        (
            "Created by".into(),
            fm.created_by.clone().unwrap_or_default(),
        ),
        ("Rows".into(), fmt::fmt_thousands(fm.num_rows)),
        ("Columns".into(), format!("{}", app.pf.num_leaf_columns())),
        ("Row groups".into(), format!("{}", fm.row_groups.len())),
        ("Size (raw)".into(), fmt::fmt_size_kib(raw)),
        ("Size (compressed)".into(), fmt::fmt_size_kib(comp)),
        ("Compression ratio".into(), fmt::fmt_ratio(ratio)),
        ("Codecs (cols)".into(), codecs_str),
        ("Encodings".into(), encs_str),
        ("Avg row size".into(), format!("{} B", avg)),
    ]
}

pub fn codec_name(c: i32) -> &'static str {
    match c {
        0 => "UNCOMPRESSED",
        1 => "SNAPPY",
        2 => "GZIP",
        3 => "LZO",
        4 => "BROTLI",
        5 => "LZ4",
        6 => "ZSTD",
        7 => "LZ4_RAW",
        _ => "UNKNOWN",
    }
}

pub fn enc_name(e: i32) -> &'static str {
    match e {
        0 => "PLAIN",
        2 => "PLAIN_DICTIONARY",
        3 => "RLE",
        4 => "BIT_PACKED",
        5 => "DELTA_BINARY_PACKED",
        6 => "DELTA_LENGTH_BYTE_ARRAY",
        7 => "DELTA_BYTE_ARRAY",
        8 => "RLE_DICTIONARY",
        9 => "BYTE_STREAM_SPLIT",
        _ => "UNKNOWN",
    }
}

pub fn ptype_name(p: i32) -> &'static str {
    match p {
        0 => "BOOLEAN",
        1 => "INT32",
        2 => "INT64",
        3 => "INT96",
        4 => "FLOAT",
        5 => "DOUBLE",
        6 => "BYTE_ARRAY",
        7 => "FIXED_LEN_BYTE_ARRAY",
        _ => "UNKNOWN",
    }
}

pub fn rep_name(r: i32) -> &'static str {
    match r {
        0 => "REQUIRED",
        1 => "OPTIONAL",
        2 => "REPEATED",
        _ => "UNKNOWN",
    }
}

pub fn render_metadata(app: &App, buf: &mut Buffer, area: &Rect) {
    if area.is_empty() {
        return;
    }
    let title_style = Style::new().bold().fg(COL_HEADER);
    let titles = vec![Title::centered("File Metadata", title_style)];
    block(
        buf,
        area,
        Borders::ALL,
        &st_fg(COL_BORDER),
        &BorderSet::default(),
        &titles,
    );
    let rows = metadata_rows(app);
    let inner = Rect::new(area.x + 1, area.y + 1, area.w.saturating_sub(2), area.h.saturating_sub(2));
    if inner.is_empty() || rows.is_empty() {
        return;
    }
    let max_label = rows.iter().map(|(l, _)| fmt::text_width(l)).max().unwrap_or(0);
    let lw = (max_label + 1) as u16;
    let off = (inner.h as usize).saturating_sub(rows.len()) / 2;
    for (i, (label, value)) in rows.iter().enumerate() {
        let y = inner.y + off as u16 + i as u16;
        if y >= inner.bottom() {
            break;
        }
        // right aligned label in lw columns
        let lab_w = fmt::text_width(label) as u16;
        let lx = inner.x + lw - lab_w;
        let _ = buf.set_string(lx, y, label, &Style::new().bold().fg(COL_BLUE));
        let _ = buf.set_string(inner.x + lw + 1, y, value, &Style::default());
    }
}

// ---------------- Schema ----------------

pub struct TreeLine {
    pub text: String,
    pub color: Option<Color>,
    pub node: usize,
    pub is_leaf: bool,
    pub is_root: bool,
    pub pipes: usize,
}

pub fn build_tree_lines(pf: &pq::ParquetFile) -> Vec<TreeLine> {
    let mut out = Vec::new();
    fn rec(pf: &pq::ParquetFile, ni: usize, prefix: &str, is_last: bool, out: &mut Vec<TreeLine>, depth: usize, pipes: usize) {
        let node = &pf.nodes[ni];
        let conn = if is_last { "\u{2514}\u{2500}" } else { "\u{2506}\u{2500}" };
        let text = format!("{}{} {}", prefix, conn, node.name);
        let is_leaf = node.children.is_empty();
        let color = if depth == 0 {
            Some(COL_BORDER)
        } else if is_leaf {
            None
        } else {
            Some(COL_GREEN)
        };
        let pipes = pipes + prefix.chars().filter(|c| *c == '\u{2506}').count();
        out.push(TreeLine {
            text,
            color,
            node: ni,
            is_leaf,
            is_root: depth == 0,
            pipes,
        });
        let n = node.children.len();
        for (k, &c) in node.children.iter().enumerate() {
            let cp = format!("{}{}  ", prefix, if is_last { " " } else { "\u{2506}" });
            rec(pf, c, &cp, k == n - 1, out, depth + 1, pipes);
        }
    }
    rec(pf, pf.root, "", true, &mut out, 0, 0);
    out
}

pub fn tree_width(pf: &pq::ParquetFile, lines: &[TreeLine]) -> usize {
    let mut mx = 0usize;
    for l in lines {
        let indent = 3 * depth_of(pf, l.node);
        let w = indent + 2 * l.pipes + 6 + fmt::text_width(&pf.nodes[l.node].name);
        if w > mx {
            mx = w;
        }
    }
    mx.max(23)
}

fn depth_of(pf: &pq::ParquetFile, ni: usize) -> usize {
    let mut d = 0usize;
    let mut cur = ni;
    while let Some(p) = pf.parent_of(cur) {
        d += 1;
        cur = p;
    }
    d
}

pub fn render_schema(app: &App, buf: &mut Buffer, area: &Rect) {
    if area.is_empty() {
        return;
    }
    let lines = build_tree_lines(&app.pf);
    let tw = tree_width(&app.pf, &lines) as u16;
    let block_w = tw + 2;
    // vertical fit
    let content_h = area.h.saturating_sub(2) as usize;
    let needs_scroll = lines.len() > content_h;
    let total_w = if needs_scroll { block_w + 1 } else { block_w };
    if area.w < total_w {
        return;
    }
    let tree_area = Rect::new(area.x, area.y, block_w, area.h);
    let mut title_text: Vec<(&str, Style)> = vec![
        ("Leaf", st_fg(COL_WHITE)),
        (", ", Style::default()),
        ("Group", st_fg(COL_GREEN)),
    ];
    if app.s_sel.is_some() {
        title_text.push((", Selected", Style::new().bold().fg(COL_HEADER)));
    }
    let joined = title_text.iter().map(|(t, _)| *t).collect::<String>();
    let bottom_title = Title {
        text: title_text,
        alignment: 1,
        position: 1,
    };
    let _ = &joined;
    let titles = vec![
        Title::centered("Schema Tree", Style::new().bold().fg(COL_HEADER)),
        bottom_title,
    ];
    block(
        buf,
        &tree_area,
        Borders::ALL,
        &st_fg(COL_BORDER),
        &BorderSet::default(),
        &titles,
    );
    // scrollbar
    let mut stats_x = tree_area.right();
    if needs_scroll {
        let sb_x = tree_area.right();
        let track = area.h;
        let thumb_len = ((content_h as f64 / lines.len() as f64) * track as f64).floor() as u16;
        let thumb_len = thumb_len.max(1);
        for i in 0..track {
            let y = area.y + i;
            let sym = if i < thumb_len { "\u{2588}" } else { VERTICAL };
            buf.set(sb_x, y, sym, &st_fg(COL_GRAY));
        }
        stats_x = sb_x + 1;
    }
    let stats_area = Rect::new(stats_x, area.y, area.right().saturating_sub(stats_x), area.h);
    // tree content
    let inner = tree_area.inner();
    let max_rows = inner.h as usize;
    let start = app.s_off.min(lines.len().saturating_sub(1));
    for (i, line) in lines.iter().skip(start).take(max_rows).enumerate() {
        let y = inner.y + i as u16;
        let selected = app.s_sel == Some(line.node);
        let st = if selected {
            Style::new().fg(COL_BLACK).bg(COL_HEADER)
        } else {
            line.color.map_or(Style::default(), st_fg)
        };
        let _ = buf.set_string(inner.x, y, &line.text, &st);
        if selected {
            let rw = inner.w.saturating_sub(fmt::text_width(&line.text) as u16);
            buf.set_style(&Rect::new(inner.x + fmt::text_width(&line.text) as u16, y, rw, 1), &st);
        }
    }
    render_stats(app, buf, &stats_area, &lines, start, max_rows);
}

pub fn stats_columns(app: &App) -> Vec<(&'static str, Vec<String>)> {
    let mut cols: Vec<(&'static str, Vec<String>)> = Vec::new();
    let leaves: Vec<usize> = leaf_order(&app.pf);
    // gather values
    let mut rep = Vec::new();
    let mut phys = Vec::new();
    let mut comp = Vec::new();
    let mut unc = Vec::new();
    let mut ratio = Vec::new();
    let mut encs = Vec::new();
    let mut codec = Vec::new();
    let mut min = Vec::new();
    let mut max = Vec::new();
    let mut nulls = Vec::new();
    let mut has_ratio = false;
    let mut has_minmax = false;
    for &li in &leaves {
        let node = &app.pf.nodes[app.pf.leaves[li].node];
        rep.push(rep_name(node.repetition).to_string());
        if node.children.is_empty() {
            phys.push(ptype_name(node.ptype).to_string());
        } else {
            phys.push("group".to_string());
        }
        // find the column chunk for this leaf
        let md = app.find_md_for_leaf(li);
        match md {
            Some(m) => {
                comp.push(fmt::fmt_size_kb(m.total_compressed_size));
                unc.push(fmt::fmt_size_kb(m.total_uncompressed_size));
                if m.total_uncompressed_size > 0 {
                    ratio.push(fmt::fmt_ratio(
                        m.total_compressed_size as f64 / m.total_uncompressed_size as f64,
                    ));
                    has_ratio = true;
                } else {
                    ratio.push(String::new());
                }
                encs.push(
                    m.encodings
                        .iter()
                        .map(|e| enc_name(*e).to_string())
                        .collect::<Vec<_>>()
                        .join(", "),
                );
                codec.push(codec_name(m.codec).to_string());
                match &m.statistics {
                    Some(s) => {
                        has_minmax = true;
                        min.push(stat_str(app, li, s.min_value.clone().or_else(|| s.min.clone())));
                        max.push(stat_str(app, li, s.max_value.clone().or_else(|| s.max.clone())));
                        nulls.push(fmt::fmt_thousands(s.null_count.unwrap_or(0)));
                    }
                    None => {
                        min.push("NULL".into());
                        max.push("NULL".into());
                        nulls.push("0".into());
                    }
                }
            }
            None => {
                comp.push(String::new());
                unc.push(String::new());
                ratio.push(String::new());
                encs.push(String::new());
                codec.push(String::new());
                min.push(String::new());
                max.push(String::new());
                nulls.push(String::new());
            }
        }
    }
    cols.push(("Repetition", rep));
    cols.push(("Physical", phys));
    cols.push(("Compressed", comp));
    cols.push(("Uncompressed", unc));
    if has_ratio {
        cols.push(("Ratio", ratio));
    }
    if has_minmax {
        cols.push(("Encodings", encs));
        cols.push(("Compression", codec));
        cols.push(("Min", min));
        cols.push(("Max", max));
    }
    cols.push(("Nulls", nulls));
    cols
}

pub fn leaf_order(pf: &pq::ParquetFile) -> Vec<usize> {
    // nodes in DFS order, both groups and leaves
    let mut out = Vec::new();
    fn rec(pf: &pq::ParquetFile, ni: usize, out: &mut Vec<usize>) {
        out.push(ni);
        for &c in &pf.nodes[ni].children {
            rec(pf, c, out);
        }
    }
    rec(pf, pf.root, &mut out);
    out
}

fn stat_str(app: &App, li: usize, raw: Option<Vec<u8>>) -> String {
    let node = &app.pf.nodes[app.pf.leaves[li].node];
    match raw {
        None => "NULL".into(),
        Some(b) => {
            let v = pq::bytes_to_val(&b, node);
            fmt::fmt_val(&v)
        }
    }
}

pub fn render_stats(
    app: &App,
    buf: &mut Buffer,
    area: &Rect,
    lines: &[TreeLine],
    start: usize,
    max_rows: usize,
) {
    if area.is_empty() {
        return;
    }
    let title_style = Style::new().bold().fg(COL_GREEN);
    let titles = vec![Title::centered("Column Statistics", title_style)];
    block(
        buf,
        area,
        Borders::ALL,
        &st_fg(COL_BORDER),
        &BorderSet::default(),
        &titles,
    );
    let inner = Rect::new(
        area.x + 1,
        area.y + 1,
        area.w.saturating_sub(2),
        area.h.saturating_sub(2),
    );
    if inner.is_empty() {
        return;
    }
    let cols = stats_columns(app);
    // widths
    let mut widths = Vec::new();
    for (name, vals) in &cols {
        let mut mx = fmt::text_width(name);
        for v in vals {
            mx = mx.max(fmt::text_width(v));
        }
        widths.push(mx + 1);
    }
    // horizontal scroll
    let avail = inner.w as usize;
    let mut xs = vec![0usize];
    for w in &widths {
        xs.push(xs.last().unwrap() + w + 1);
    }
    let total = xs.last().copied().unwrap_or(0).saturating_sub(1);
    let mut off = app.s_hoff;
    if total > avail {
        let mut k = 0usize;
        for i in 0..cols.len() {
            if xs[i] <= total - avail {
                k = i;
            } else {
                break;
            }
        }
        if off > k {
            off = k;
        }
    } else {
        off = 0;
    }
    // header
    let hdr_y = inner.y;
    let mut cx = inner.x;
    for (i, (name, _)) in cols.iter().enumerate() {
        if i < off {
            continue;
        }
        let x = inner.x + (xs[i] - xs[off]) as u16;
        if x >= inner.right() {
            break;
        }
        let w = (widths[i] as u16).min(inner.right().saturating_sub(x));
        let _ = buf.set_string(x, hdr_y, name, &Style::new().bold().fg(COL_HEADER));
        // pad to width
        for k in fmt::text_width(name) as u16..w {
            buf.set(x + k, hdr_y, " ", &Style::new().bold().fg(COL_HEADER));
        }
        let _ = cx;
    }
    // rows
    for (i, line) in lines.iter().skip(start).take(max_rows.saturating_sub(0)).enumerate() {
        let y = inner.y + 1 + i as u16;
        if y >= inner.bottom() {
            break;
        }
        let node = &app.pf.nodes[line.node];
        let selected = app.s_sel == Some(line.node);
        if selected {
            buf.set_style(&Rect::new(inner.x, y, inner.w, 1), &Style::new().fg(COL_BLACK).bg(COL_HEADER));
        }
        let row_st = if node.children.is_empty() {
            Style::default()
        } else {
            st_fg(COL_GREEN)
        };
        for (ci, (_, vals)) in cols.iter().enumerate() {
            if ci < off {
                continue;
            }
            let x = inner.x + (xs[ci] - xs[off]) as u16;
            if x >= inner.right() {
                break;
            }
            let v = vals.get(i).map(|s| s.as_str()).unwrap_or("");
            let _ = buf.set_string(x, y, v, &row_st);
        }
    }
}

