                                2 => app.s_hoff = app.s_hoff.saturating_sub(1),
                                3 => app.rg_idx = app.rg_idx.saturating_sub(1),
                                _ => {}
                            }
                            dirty = true;
                        }
                        crossterm::event::KeyCode::Char('d') => {
                            if app.tab == 0 {
                                app.scroll_rows(term.prev.h as u16 - 4, 1);
                                dirty = true;
                            }
                        }
                        crossterm::event::KeyCode::Char('u') => {
                            if app.tab == 0 {
                                app.scroll_rows(term.prev.h as u16 - 4, -1);
                                dirty = true;
                            }
                        }
                        crossterm::event::KeyCode::Char('D') | crossterm::event::KeyCode::PageDown => {
                            if app.tab == 0 {
                                app.scroll_rows(term.prev.h as u16 - 4, 1);
                                dirty = true;
                            }
                        }
                        crossterm::event::KeyCode::Char('U') | crossterm::event::KeyCode::PageUp => {
                            if app.tab == 0 {
                                app.scroll_rows(term.prev.h as u16 - 4, -1);
                                dirty = true;
                            }
                        }
                        _ => {}
                    }
                }
            }
            crossterm::event::Event::Resize(w, h) => {
                term.resize(w, h);
                dirty = true;
            }
            _ => {}
        }
        if app.quitted {
            let _ = write!(out, "\x1b[?1049l\x1b[?25h");
            let _ = out.flush();
            let _ = crossterm::terminal::disable_raw_mode();
            return Ok(());
        }
        if dirty {
            render::render(&app, &mut term);
            let _ = out.write_all(&term.out);
            let _ = out.flush();
            term.out.clear();
        }
    }
    let _ = write!(out, "\x1b[?1049l\x1b[?25h");
    let _ = out.flush();
    let _ = crossterm::terminal::disable_raw_mode();
    Ok(())
}

