    pub fn schema_nodes(&self) -> Vec<usize> {
        let mut out = Vec::new();
        fn rec(pf: &ParquetFile, ni: usize, out: &mut Vec<usize>) {
            out.push(ni);
            for &c in &pf.nodes[ni].children {
                rec(pf, c, out);
            }
        }
        rec(&self.pf, self.pf.root, &mut out);
        out
    }
    /// Leaf nodes in DFS order (skipping the root) used for schema selection.
    pub fn selectable(&self) -> Vec<usize> {
        let all = self.schema_nodes();
        let leaves: Vec<usize> = all
            .iter()
            .copied()
            .filter(|&n| self.pf.nodes[n].children.is_empty())
            .collect();
        leaves
    }
    pub fn schema_down(&mut self) {
        let sel = self.selectable();
        if sel.is_empty() {
            return;
        }
        let next = match self.s_sel {
            None => sel[0],
            Some(n) => {
                let i = sel.iter().position(|&x| x == n).unwrap_or(usize::MAX);
                if i == usize::MAX {
                    sel[0]
                } else if i + 1 < sel.len() {
                    sel[i + 1]
                } else {
                    n
                }
            }
        };
        self.s_sel = Some(next);
        self.ensure_schema_visible();
    }
    pub fn schema_up(&mut self) {
        let sel = self.selectable();
        if sel.is_empty() {
            return;
        }
        match self.s_sel {
            None => {}
            Some(n) => {
                let i = sel.iter().position(|&x| x == n).unwrap_or(usize::MAX);
                if i == usize::MAX {
                    self.s_sel = None;
                } else if i == 0 {
                    self.s_sel = None;
                } else {
                    self.s_sel = Some(sel[i - 1]);
                    self.ensure_schema_visible();
                }
            }
        }
