"""Compare the reference and my build for a given file/size/keys."""
import subprocess,time,re,sys,os
REF='/workspace/executable'
MINE=os.environ.get('MINE','/workspace/target/debug/parqeye')
run=lambda c: subprocess.run(c,capture_output=True)
def vis(l): return re.sub(r'\x1b\[[0-9;]*[A-Za-z]','',l)
def styled(l): return l
def shot(exe, f, w, h, keys):
    run(['tmux','kill-server']); time.sleep(0.2)
    run(['tmux','new-session','-d','-x',str(w),'-y',str(h),'-s','s1','-c','/workspace','env TERM=xterm-256color '+exe+' '+f])
    run(['tmux','set-option','-t','s1','remain-on-exit','on'])
    time.sleep(0.7)
    for k in keys:
        if k.startswith('^'): run(['tmux','send-keys','-t','s1',k[1:]])
        else: run(['tmux','send-keys','-t','s1','-l',k])
        time.sleep(0.3)
    time.sleep(0.2)
    d=run(['tmux','capture-pane','-p','-t','s1','-e']).stdout.decode('utf-8','replace').split('\n')
    if d and d[-1]=='': d.pop()
    return d
def main():
    f=sys.argv[1]; w=int(sys.argv[2]); h=int(sys.argv[3])
    keys=sys.argv[4].split('|') if len(sys.argv)>4 else []
    verbose = 'v' in sys.argv
    a=shot(REF,f,w,h,keys); b=shot(MINE,f,w,h,keys)
    diffs=0
    for i,(x,y) in enumerate(zip(a,b)):
        if x!=y:
            diffs+=1
            if diffs<=int(os.environ.get('MAXD','12')): print(f'{i:3d} REF={x!r}\n    MINE={y!r}')
    if len(a)!=len(b): print('LEN DIFF', len(a), len(b))
    print(f'{f} {w}x{h} keys={keys}: diffs={diffs}')
main()
