p='src/pq/metadata.rs'; s=open(p).read()
import re
# wrap every parse_* function's field loop with enter/leave
funcs = ['parse_logical_type','parse_statistics','parse_column_meta','parse_column_chunk','parse_row_group','parse_schema_element','parse_file_metadata']
for f in funcs:
    # find the function start and the "loop {" after it
    i = s.index('fn %s(' % f)
    j = s.index('let mut t = Thrift', i) if 'let mut t = Thrift' in s[i:i+400] else -1
    # find the first "loop {" after i
    k = s.index('loop {', i)
    indent = s[k+6:k+12]
    # insert enter() before the loop and leave() after
    line_start = s.rfind('\n', 0, k)+1
    indent_of_loop = s[line_start:k]
    s = s[:k] + 'let saved = t.enter();\n' + indent_of_loop + s[k:]
    # find the matching closing brace of the loop: the first "\n    }\n" after k with the same indent
    m = re.compile(r'\n(' + re.escape(indent_of_loop.strip()) + r')\}\n', re.S).search(s, k)
    if m:
        end = m.end()
        s = s[:end-2] + '\n' + indent_of_loop + 't.leave(saved);\n' + indent_of_loop + '}\n' + s[end:]
open(p,'w').write(s)
