import sys; sys.path.insert(0,'/tmp/pyq')
import pq
# scan for page headers
res=[]
i=0
while i < len(b)-4:
    try:
        hdr = pq.Compact(b, i).read_struct()
    except Exception as e:
        i+=1; continue
    if 1 in hdr and 2 in hdr and 3 in hdr and isinstance(hdr[1],int) and hdr[1] in (0,2,3):
        pt=hdr[1]; unc=hdr[2]; comp=hdr[3]
        if isinstance(unc,int) and isinstance(comp,int) and 0<=comp<=2000 and unc==comp:
            res.append((i,pt,unc,comp))
    i+=1
for r in res[:25]: print(r)
